const hoje=()=>{const d=new Date();return d.toLocaleDateString("pt-BR")};
const ordNow=(()=>{let last=0;return()=>{let t=Date.now();if(t<=last)t=last+1;last=t;return t}})();
function toast(m,ms=2600){const t=document.createElement("div");t.className="toast";t.textContent=m;document.body.appendChild(t);setTimeout(()=>t.remove(),ms)}
function busy(msg){const b=document.createElement("div");b.className="busy";b.innerHTML='<div class="spin"></div><div id="busyMsg">'+esc(msg)+'</div>';document.body.appendChild(b);return{set:m=>{const e=b.querySelector("#busyMsg");if(e)e.textContent=m},close:()=>b.remove()}}
const slug=s=>String(s||"").normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^A-Za-z0-9]+/g,"_").replace(/^_|_$/g,"").toUpperCase();
const debounce=(f,ms)=>{let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>f(...a),ms)}};
function b64ToU8(b){const s=atob(b),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return u}
function saveFile(blob,name){
  return new Promise(res=>{
    const file=new File([blob],name,{type:blob.type||"application/octet-stream"});
    let podeComp=false;try{podeComp=!!(navigator.canShare&&navigator.canShare({files:[file]}))}catch(e){}
    const mb=(blob.size/1048576).toFixed(1);
    const m=sheet(`<h3>Arquivo pronto</h3><div class="mu" style="margin-bottom:12px">${esc(name)} · ${mb} MB</div>
      ${podeComp?`<button class="btn p w" id="sfShare" style="margin-bottom:8px">📤 Compartilhar (WhatsApp, e-mail, Drive…)</button>`:""}
      <button class="btn w ${podeComp?"":"p"}" id="sfDown">⬇ Baixar para o aparelho</button>
      <div class="mu" style="margin-top:10px">Conteúdo sensível: prefira canais institucionais.</div>`);
    let feito=false;const fim=v=>{if(feito)return;feito=true;res(v)};
    m.addEventListener("remove-modal",()=>fim(false));
    const baixar=()=>{const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},60000);toast("Download iniciado (pasta Downloads)",3500);fim(true);m.remove()};
    m.querySelector("#sfDown").onclick=baixar;
    const sh=m.querySelector("#sfShare");
    if(sh)sh.onclick=async()=>{try{await navigator.share({files:[file],title:name});fim(true);m.remove()}
      catch(e){if(e.name==="AbortError")return;toast("Não foi possível compartilhar ("+e.name+"). Use Baixar.",4500)}};
  });
}

/* ====================== INDEXEDDB ====================== */
let DB;
function openDB(){return new Promise((res,rej)=>{
  const r=indexedDB.open("quantitativos-campo",1);
  r.onupgradeneeded=()=>{const d=r.result;
    d.createObjectStore("estacoes",{keyPath:"id"});
    const s=d.createObjectStore("secoes",{keyPath:"id"});s.createIndex("estacaoId","estacaoId");
    const a=d.createObjectStore("ambientes",{keyPath:"id"});a.createIndex("estacaoId","estacaoId");
    const i=d.createObjectStore("itens",{keyPath:"id"});i.createIndex("estacaoId","estacaoId");i.createIndex("ambienteId","ambienteId");
    const f=d.createObjectStore("fotos",{keyPath:"id"});f.createIndex("estacaoId","estacaoId");f.createIndex("ambienteId","ambienteId");
    const sv=d.createObjectStore("servicos",{keyPath:"id"});sv.createIndex("estacaoId","estacaoId");sv.createIndex("ambienteId","ambienteId");
    const md=d.createObjectStore("medicoes",{keyPath:"id"});md.createIndex("estacaoId","estacaoId");md.createIndex("ambienteId","ambienteId");
    d.createObjectStore("blobs",{keyPath:"id"});
    d.createObjectStore("config",{keyPath:"key"});
  };
  r.onsuccess=()=>{DB=r.result;res()};r.onerror=()=>rej(r.error);
})}
const P=req=>new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});
const st=(n,m="readonly")=>DB.transaction(n,m).objectStore(n);
const dbGet=(n,k)=>P(st(n).get(k));
const dbAll=n=>P(st(n).getAll());
const dbBy=(n,idx,v)=>P(st(n).index(idx).getAll(v));
const dbPut=(n,o)=>P(st(n,"readwrite").put(o));
const dbDel=(n,k)=>P(st(n,"readwrite").delete(k));
/* Transação multi-store: tudo ou nada */
function txRun(stores,fn){return new Promise((res,rej)=>{let out;const t=DB.transaction(stores,"readwrite");
  t.oncomplete=()=>res(out);t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error||new Error("Transação cancelada"));
  try{out=fn(t)}catch(e){try{t.abort()}catch(_){};rej(e)}})}
/* Fila única: gravações executam em série, nunca em paralelo */
let chain=Promise.resolve();const pend={};
function enqueue(f){const r=chain.then(f);chain=r.catch(e=>console.error(e));return r}
window.addEventListener("unhandledrejection",e=>{e.preventDefault();saveErr(e.reason,"inesperado")});
let ultimoErro=0;function saveErr(e,tipo){if(Date.now()-ultimoErro<1500)return;ultimoErro=Date.now();const q=/quota|QuotaExceeded/i.test(String(e&&(e.name+e.message)));
  alert(q?"Sem espaço no aparelho: a última alteração NÃO foi salva. Libere espaço e faça backup.":tipo==="inesperado"?"Erro inesperado: "+(e&&e.message||e)+"\nA última ação pode não ter sido concluída. Confira antes de continuar.":"Erro ao salvar: "+(e&&e.message))}
/* ---------- registro de alteração por estação (para o aviso de backup) ---------- */
const ALT={};let altT={};
function alterou(estId){if(!estId)return;ALT[estId]=Date.now();clearTimeout(altT[estId]);altT[estId]=setTimeout(()=>{dbPut("config",{key:"alteradoEst_"+estId,v:ALT[estId]}).catch(()=>{})},300)}
const limitar=(t,max)=>{t=String(t||"").trim();if(t.length>max){toast(`Texto cortado em ${max} caracteres`);t=t.slice(0,max)}return t};
function setSaveSt(t){const el=document.getElementById("saveSt");if(el){el.textContent=t;el.className=t?"on":""}}
function deb(key,f,ms=400){if(pend[key])clearTimeout(pend[key].t);setSaveSt("Salvando…");
  pend[key]={f,t:setTimeout(()=>{delete pend[key];enqueue(f).then(()=>{if(!Object.keys(pend).length)setSaveSt("✓ Salvo")}).catch(e=>{setSaveSt("⚠ Erro ao salvar");saveErr(e)})},ms)}}
async function flushSaves(){for(const k of Object.keys(pend)){clearTimeout(pend[k].t);const f=pend[k].f;delete pend[k];enqueue(f).catch(e=>{setSaveSt("⚠ Erro ao salvar");saveErr(e)})}
  try{await chain}catch(e){} if(document.getElementById("saveSt")&&document.getElementById("saveSt").textContent==="Salvando…")setSaveSt("✓ Salvo")}
/* leitura-modificação-gravação sempre do banco, dentro da fila */
/* updRaw: só usar DENTRO da fila; upd: chamadas de fora da fila */
const updRaw=(store,id,fn)=>(new Promise((res,rej)=>{const t=DB.transaction(store,"readwrite"),os=t.objectStore(store);let o;
  const g=os.get(id);g.onsuccess=()=>{o=g.result;if(o&&fn(o)!==false)os.put(o)};t.oncomplete=()=>res(o);t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error)}));
const upd=(store,id,fn)=>enqueue(()=>updRaw(store,id,fn));
/* move um registro uma posição dentro do seu grupo, lendo o grupo do banco na hora */
const moverOrdem=(store,index,val,grupo,id,dir)=>enqueue(()=>txRun([store],t=>{const os=t.objectStore(store);const r=os.index(index).getAll(val);
  r.onsuccess=()=>{const g=r.result.filter(grupo).sort((a,b)=>a.ordem-b.ordem);const i=g.findIndex(x=>x.id===id),j=i+dir;
    if(i<0||j<0||j>=g.length)return;const o=g[i].ordem;g[i].ordem=g[j].ordem;g[j].ordem=o;if(g[i].ordem===g[j].ordem)g[j].ordem+=dir;os.put(g[i]);os.put(g[j])}}));
const swapOrdem=(store,id1,id2)=>enqueue(()=>txRun([store],t=>{const os=t.objectStore(store);const a=os.get(id1),b=os.get(id2);
  b.onsuccess=()=>{const A=a.result,B=b.result;if(A&&B){const o=A.ordem;A.ordem=B.ordem;B.ordem=o;os.put(A);os.put(B)}}}));
/* apaga uma estação inteira dentro de uma transação já aberta; chama done() ao terminar de enfileirar */
function delEstTx(t,estId,done){let n;const fim=()=>{if(--n===0){t.objectStore("estacoes").delete(estId);done&&done()}};
  n=SUB.length;for(const sn of SUB){const r=t.objectStore(sn).index("estacaoId").getAllKeys(estId);
    r.onsuccess=()=>{for(const k of r.result){t.objectStore(sn).delete(k);if(sn==="fotos")t.objectStore("blobs").delete(k)}fim()}}}
const SUB=["secoes","ambientes","servicos","itens","medicoes","fotos"];
const ALL=["estacoes",...SUB,"blobs"];
async function cfg(k,def){const r=await dbGet("config",k);return r?r.v:def}
const setCfg=(k,v)=>dbPut("config",{key:k,v});
async function getModelo(){return await cfg("modelo",null)||JSON.parse(JSON.stringify(MODELO_PADRAO))}

/* ====================== DADOS DA ESTAÇÃO ====================== */
async function loadEst(id){
  const est=await dbGet("estacoes",id);if(!est)return null;
  const [secoes,ambientes,itens,fotos,servicos,medicoes]=await Promise.all(["secoes","ambientes","itens","fotos","servicos","medicoes"].map(k=>dbBy(k,"estacaoId",id)));
  const by=k=>(a,b)=>a[k]-b[k];
  secoes.sort(by("ordem"));ambientes.sort(by("ordem"));itens.sort(by("ordem"));fotos.sort(by("ordem"));servicos.sort(by("ordem"));medicoes.sort(by("ordem"));
  for(const a of ambientes)if(!TIPOS[a.tipo])a.tipo=inferTipo(a.nome);
  return {est,secoes,ambientes,itens,fotos,servicos,medicoes};
}
/* Numeração idêntica à do relatório: 1-4 fixos, etapas a partir de 5; ambientes/etapas sem conteúdo não recebem número */
function numerar(D){
  const N={sec:{},amb:{},item:{},foto:{},ordemFotos:[]};let s=4,fig=0;
  const temConteudo=a=>D.itens.some(i=>i.ambienteId===a.id)||D.fotos.some(f=>f.ambienteId===a.id);/* medições sem foto não entram no relatório fotográfico */
  for(const sec of D.secoes){
    const ambs=D.ambientes.filter(a=>a.secaoId===sec.id&&temConteudo(a));
    if(!ambs.length)continue;
    s++;N.sec[sec.id]=String(s);let m=0;
    for(const a of ambs){
      m++;const an=s+"."+m;N.amb[a.id]=an;let k=0;
      const its=D.itens.filter(i=>i.ambienteId===a.id);
      for(const it of its){k++;N.item[it.id]=an+"."+k}
      for(const f of fotosOrdenadas(D,a.id)){fig++;N.foto[f.id]=fig;N.ordemFotos.push(f)}
    }
  }
  N.ultimaSecao=s;return N;
}
function fotosOrdenadas(D,ambId){
  const its=D.itens.filter(i=>i.ambienteId===ambId);const out=[];
  for(const it of its)out.push(...D.fotos.filter(f=>f.ambienteId===ambId&&f.itemId===it.id));
  const meds=(D.medicoes||[]).filter(m=>m.ambienteId===ambId).sort((a,b)=>cmpCod(a.cod,b.cod)||a.ordem-b.ordem);
  for(const m of meds)out.push(...D.fotos.filter(f=>f.ambienteId===ambId&&f.medicaoId===m.id&&!(f.itemId&&its.some(i=>i.id===f.itemId))));
  out.push(...D.fotos.filter(f=>f.ambienteId===ambId&&!out.includes(f)));
  return out;
}
function legendaFinal(D,f){
  if(f.legenda&&f.legenda.trim())return f.legenda.trim();
  const md=f.medicaoId&&(D.medicoes||[]).find(m=>m.id===f.medicaoId);
  if(md){const s=medSvc(md),a=D.ambientes.find(x=>x.id===md.ambienteId),r=a?calcMed(md,a):{};let d=s.d;if(d.length>90)d=d.slice(0,87).replace(/\s+\S*$/,"")+"…";
    return `Item ${md.cod} – ${d}${md.local?" ("+md.local+")":""}${isFinite(r.q1)?": "+fq(r.q1,s.u)+" "+s.u:""}.`}
  const it=f.itemId&&D.itens.find(i=>i.id===f.itemId);
  if(it&&it.texto.trim()){let t=it.texto.trim().split(/\n/)[0].replace(/[;:.\s]+$/,"");if(t.length>110)t=t.slice(0,107).replace(/\s+\S*$/,"")+"…";return t+"."}
  const a=D.ambientes.find(x=>x.id===f.ambienteId);return a?a.nome+".":"";
}
function delAmbiente(id){return enqueue(()=>txRun(["ambientes","itens","servicos","medicoes","fotos","blobs"],t=>{
  for(const sn of ["itens","servicos","medicoes"]){const ri=t.objectStore(sn).index("ambienteId").getAllKeys(id);ri.onsuccess=()=>ri.result.forEach(k=>t.objectStore(sn).delete(k))}
  const rf=t.objectStore("fotos").index("ambienteId").getAllKeys(id);rf.onsuccess=()=>rf.result.forEach(k=>{t.objectStore("fotos").delete(k);t.objectStore("blobs").delete(k)});
  t.objectStore("ambientes").delete(id)}))}
function delEstacao(id){return enqueue(()=>txRun(ALL,t=>delEstTx(t,id)))}

/* ====================== FOTOS ====================== */
async function decodeImg(file){
  try{return await createImageBitmap(file,{imageOrientation:"from-image"})}
  catch(e){return await new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=URL.createObjectURL(file)})}
}
function toJpeg(img,max,q){
  const w0=img.width,h0=img.height,sc=Math.min(1,max/Math.max(w0,h0));
  const c=document.createElement("canvas");c.width=Math.round(w0*sc);c.height=Math.round(h0*sc);
  c.getContext("2d").drawImage(img,0,0,c.width,c.height);
  return new Promise(r=>c.toBlob(b=>r({blob:b,w:c.width,h:c.height}),"image/jpeg",q));
}
let lastPos=null,geoWatch=null;
function geoStart(){if(OPC.gps!==true)return;if(geoWatch!==null||!navigator.geolocation)return;try{geoWatch=navigator.geolocation.watchPosition(p=>{lastPos={lat:+p.coords.latitude.toFixed(6),lon:+p.coords.longitude.toFixed(6),t:Date.now()}},()=>{},{enableHighAccuracy:true,maximumAge:60000})}catch(e){}}
function geoStop(){if(geoWatch!==null){navigator.geolocation.clearWatch(geoWatch);geoWatch=null}}
async function espacoLivreMB(){try{const e=await navigator.storage.estimate();return (e.quota-e.usage)/1048576}catch(_){return Infinity}}
async function addFotos(files,alvo){
  const livre=await espacoLivreMB();
  if(livre<files.length*1+30){alert(`Pouco espaço disponível para o app (~${Math.max(0,livre).toFixed(0)} MB). Faça backup e libere espaço no celular antes de continuar.`);return}
  const b=busy("Processando foto(s)…");let n=0,ok=0;
  try{
    for(const file of files){
      n++;b.set(`Processando foto ${n} de ${files.length}…`);
      const img=await decodeImg(file);
      const full=await toJpeg(img,OPC.resolucao===2400?2400:1600,OPC.resolucao===2400?.85:.8),th=await toJpeg(img,320,.65);
      if(img.close)img.close();
      const id=uid(),gps=OPC.gps&&lastPos&&Date.now()-lastPos.t<300000?{lat:lastPos.lat,lon:lastPos.lon}:null;
      if(!full.blob||!full.blob.size)throw new Error("falha ao converter a imagem");
      const meta={id,estacaoId:alvo.estacaoId,ambienteId:alvo.ambienteId,itemId:alvo.itemId||null,medicaoId:alvo.medicaoId||null,legenda:"",data:new Date(file.lastModified&&files.length>1?file.lastModified:Date.now()).toISOString(),lat:gps?gps.lat:null,lon:gps?gps.lon:null,w:full.w,h:full.h,bytes:full.blob.size,ordem:ordNow()};
      await enqueue(()=>txRun(["blobs","fotos"],t=>{t.objectStore("blobs").put({id,full:full.blob,thumb:th.blob});t.objectStore("fotos").put(meta)}));
      ok++;
    }
    toast(ok>1?ok+" fotos adicionadas":"Foto adicionada");
  }catch(e){console.error(e);const q=/quota/i.test(e.name+e.message);
    alert((q?"Sem espaço no aparelho. ":"Erro ao processar a foto "+n+": "+e.message+". ")+(ok?`${ok} foto(s) anterior(es) foram salvas; `:"")+"a foto com erro não foi salva.")}
  finally{b.close()}
}
const urlCache=new Map();
async function thumbURL(id){if(urlCache.has(id))return urlCache.get(id);const r=await dbGet("blobs",id);if(!r)return"";const u=URL.createObjectURL(r.thumb);urlCache.set(id,u);return u}
function clearURLs(){for(const u of urlCache.values())URL.revokeObjectURL(u);urlCache.clear()}

/* ====================== DITADO ====================== */
let rec=null;
function ditar(ta,onDone,btn){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(rec){rec.stop();return}
  if(!OPC.ditado){toast("Ditado desligado nas Configurações.");ta.focus();return}
  if(!SR){toast("Ditado indisponível neste navegador. Use o microfone do teclado.",4000);ta.focus();return}
  const r=new SR();r.lang="pt-BR";r.continuous=true;r.interimResults=true;
  const base=ta.value.replace(/\s+$/,"");let fin="";
  r.onresult=e=>{let inter="";for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)fin+=(fin?" ":"")+t.trim();else inter+=t}
    ta.value=(base?base+" ":"")+fin+(inter?" "+inter:"");ta.dispatchEvent(new Event("input",{bubbles:true}))};
  r.onerror=e=>{if(e.error==="not-allowed")toast("Permita o microfone para usar o ditado.");else if(e.error==="network")toast("Ditado precisa de internet. Use o microfone do teclado.",4000)};
  r.onend=()=>{rec=null;btn&&btn.classList.remove("rec");ta.value=(base?base+" ":"")+fin;ta.dispatchEvent(new Event("input",{bubbles:true}));onDone&&onDone()};
  rec=r;btn&&btn.classList.add("rec");r.start();toast("Ouvindo… toque de novo para parar");
}

