  const bkEst={},altEst={};for(const e of ests){bkEst[e.id]=Math.max(lastBk,await cfg("ultimoBackupEst_"+e.id,0));altEst[e.id]=ALT[e.id]||await cfg("alteradoEst_"+e.id,0)}
  /* precisa de backup quando houve alteração depois do último backup confirmado (sem registro de alteração: regra antiga de 20 h) */
  const precisa=e=>altEst[e.id]?altEst[e.id]>bkEst[e.id]:(!bkEst[e.id]||Date.now()-bkEst[e.id]>20*3600e3);
