async function viewAmbiente(id,sub){
  const amb0=await dbGet("ambientes",id);if(!amb0)return(location.hash="#/");
  const D=await loadEst(amb0.estacaoId);const N=numerar(D);const amb=D.ambientes.find(a=>a.id===id);
  const lista=D.secoes.flatMap(s=>D.ambientes.filter(a=>a.secaoId===s.id));const idx=lista.findIndex(a=>a.id===id);
  if(sub!=="notas"){if(ctx.ambId!==id)ctx.filtroSvc="todos";ctx={...ctx,estId:amb.estacaoId,ambId:id,D,N,amb};geoStart();
    if(OPC.gps===null&&!document.querySelector(".modal"))setTimeout(perguntarGps,300);return viewQuantAmb(amb,D,N,lista,idx)}
  const prev=lista[idx-1],next=lista[idx+1];
  const its=D.itens.filter(i=>i.ambienteId===id);
  if(ctx.ambId!==id)ctx={...ctx,ativo:its.length?its[its.length-1].id:"geral"};
  else if(ctx.ativo!=="geral"&&!its.some(i=>i.id===ctx.ativo))ctx.ativo=its.length?its[its.length-1].id:"geral";
  ctx={...ctx,estId:amb.estacaoId,ambId:id,D,N,amb};
  geoStart();
  if(OPC.gps===null&&!document.querySelector(".modal"))setTimeout(perguntarGps,300);
  const sec=D.secoes.find(s=>s.id===amb.secaoId);
  const fotoHtml=async f=>`<span class="fig"><img data-a="foto" data-id="${esc(f.id)}" src="${await thumbURL(f.id)}" alt="Figura ${N.foto[f.id]||""} — abrir" role="button" tabindex="0"><b>${N.foto[f.id]||""}</b></span>`;
  let itemsHtml="";
  for(const it of its){
    const fs=D.fotos.filter(f=>f.ambienteId===id&&f.itemId===it.id);
    itemsHtml+=`<div class="card item ${ctx.ativo===it.id?"on":""}" data-a="ativar" data-id="${esc(it.id)}">
      <div class="row"><span class="num">${N.item[it.id]||""}</span><span class="grow"></span>
      <button class="btn sm" data-a="itUp" data-id="${esc(it.id)}" aria-label="Subir anotação">↑</button><button class="btn sm" data-a="itDown" data-id="${esc(it.id)}" aria-label="Descer anotação">↓</button><button class="btn sm d" data-a="itDel" data-id="${esc(it.id)}" aria-label="Excluir anotação">🗑</button></div>
      <textarea maxlength="${UI_MAX.txt}" data-a="itTxt" data-id="${esc(it.id)}" aria-label="Texto da anotação ${esc(N.item[it.id]||"")}" placeholder="Descreva a ocorrência…">${esc(it.texto)}</textarea>
      <div class="thumbs">${(await Promise.all(fs.map(fotoHtml))).join("")}</div>
      <div class="tools">${OPC.ditado?`<button class="btn" data-a="ditarIt" data-id="${esc(it.id)}">🎤 Ditar</button>`:""}<button class="btn" data-a="cam" data-id="${esc(it.id)}">📷 Foto</button><button class="btn" data-a="gal" data-id="${esc(it.id)}">🖼 Galeria</button></div></div>`;
  }
  const gerais=D.fotos.filter(f=>f.ambienteId===id&&!f.medicaoId&&(!f.itemId||!its.some(i=>i.id===f.itemId)));
  const alvo=ctx.ativo==="geral"?"fotos gerais":N.item[ctx.ativo];
  app.innerHTML=topbar(amb.nome,(sec?sec.titulo:"")+" · "+(idx+1)+"/"+lista.length,"#/e/"+amb.estacaoId,`<button class="ib" aria-label="Ambiente anterior" ${prev?`data-a="go" data-h="#/a/${esc(prev.id)}/notas"`:"disabled style='opacity:.3'"}>‹</button><button class="ib" aria-label="Próximo ambiente" ${next?`data-a="go" data-h="#/a/${esc(next.id)}/notas"`:"disabled style='opacity:.3'"}>›</button>`)+
  `<main><nav class="tabs"><a href="#/a/${esc(id)}">Quantitativos</a><a href="#/a/${esc(id)}/notas" class="on">Anotações e fotos</a></nav><div class="row" style="margin-bottom:10px"><span class="num">${N.amb[id]||"–"}</span><span class="grow mu">Toque no status para alterar</span><button class="chip st-${esc(amb.status)}" data-a="status" aria-label="Status: ${esc(amb.status)}. Tocar para alterar">${esc(amb.status)}</button></div>
  ${itemsHtml||'<div class="empty">Caderno vazio.<br>Use <b>＋ Anotação</b>${OPC.ditado?" ou <b>🎤 Ditar</b>":""} para registrar a primeira ocorrência.</div>'}
  <div class="card item ${ctx.ativo==="geral"?"on":""}" data-a="ativar" data-id=""><div class="row"><b class="grow">Fotos gerais do ambiente</b><button class="btn sm" data-a="cam" data-id="" aria-label="Foto geral pela câmera">📷</button><button class="btn sm" data-a="gal" data-id="" aria-label="Foto geral da galeria">🖼</button></div>
  <div class="thumbs">${(await Promise.all(gerais.map(fotoHtml))).join("")||'<span class="mu">Nenhuma.</span>'}</div></div>
  </main>
  <div class="bar"><button class="btn" data-a="novoIt">＋ Anotação</button>${OPC.ditado?`<button class="btn" data-a="novoItDitar">🎤 Ditar<small>nova anotação</small></button>`:""}<button class="btn p" data-a="cam" data-id="${esc(ctx.ativo==="geral"?"":ctx.ativo||"")}" aria-label="Tirar foto">📷 Foto<small>→ ${esc(alvo)}</small></button></div>`;
  if(ctx.focar){const t=app.querySelector(`textarea[data-id="${ctx.focar}"]`);ctx.focar=null;if(t){t.focus();t.scrollIntoView({block:"center"});if(ctx.ditarAuto){ctx.ditarAuto=false;ditar(t,null,app.querySelector(`[data-a="ditarIt"][data-id="${t.dataset.id}"]`))}}}
}
function selecionar(v){ctx.ativo=v;app.querySelectorAll(".item.on").forEach(x=>x.classList.remove("on"));
  const c=app.querySelector(`[data-a="ativar"][data-id="${v==="geral"?"":CSS.escape(v)}"]`);if(c)c.classList.add("on");
  const b=app.querySelector('.bar [data-a="cam"]');if(b){b.dataset.id=v==="geral"?"":v;b.querySelector("small").textContent="→ "+(v==="geral"?"fotos gerais":(ctx.N.item[v]||""))}}
function perguntarGps(){if(OPC.gps!==null||document.querySelector(".modal"))return;
  const m=sheet(`<h3>Registrar a localização nas fotos?</h3><div class="mu">O GPS é gravado em cada foto e aparece no índice do ZIP de fotos. Dá para mudar depois em Configurações.</div>
    <div class="row" style="margin-top:14px"><button class="btn grow" id="gNo">Não</button><button class="btn p grow" id="gSim">Sim, registrar</button></div>`);
  const def=async v=>{OPC.gps=v;await enqueue(()=>setCfg("opcoes",{...OPC}));if(v)geoStart();m.remove();toast(v?"GPS ligado":"GPS desligado")};
  m.querySelector("#gNo").onclick=()=>def(false);m.querySelector("#gSim").onclick=()=>def(true)}
async function rerenderKeepScroll(){const y=scrollY;await render();scrollTo(0,y)}

/* ---------- MODAIS ---------- */
/* Voltar do Android fecha o modal do topo. Quando o próprio app fecha um modal, ele volta uma entrada do histórico
   e ignora o popstate resultante (contador), mesmo que outro modal tenha sido aberto antes do popstate chegar. */
let popIgnorar=0;
window.addEventListener("popstate",()=>{if(popIgnorar>0){popIgnorar--;return}const ms=document.querySelectorAll(".modal");if(ms.length){const m=ms[ms.length-1];m._pop=true;m.remove()}});
function sheet(html){const m=document.createElement("div");m.className="modal";
  const rm=m.remove.bind(m);m.remove=()=>{if(!m.isConnected)return;rm();m.dispatchEvent(new Event("remove-modal"));if(m._hist&&!m._pop){m._hist=false;popIgnorar++;history.back()}};
  try{history.pushState({modal:1},"");m._hist=true}catch(e){}m.innerHTML=`<div class="sheet" role="dialog" aria-modal="true" tabindex="-1">${html}</div>`;m.addEventListener("click",e=>{if(e.target===m)m.remove()});document.body.appendChild(m);
  m.querySelectorAll(".opt").forEach(o=>{if(!o.querySelector("input")){o.setAttribute("role","button");o.tabIndex=0}});const h=m.querySelector("h3");if(h){h.id="dlg"+uid();m.firstChild.setAttribute("aria-labelledby",h.id)}
  setTimeout(()=>m.firstChild.focus(),0);return m}
document.addEventListener("keydown",e=>{if(e.key==="Escape"){const ms=document.querySelectorAll(".modal");if(ms.length)ms[ms.length-1].remove()}
  if(e.key==="Tab"){const ms=document.querySelectorAll(".modal");if(ms.length){const sh=ms[ms.length-1].firstChild;const f=[...sh.querySelectorAll('button,input,select,textarea,[tabindex="0"],a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null);
    if(f.length){const a=f[0],z=f[f.length-1];if(!sh.contains(document.activeElement)){e.preventDefault();a.focus()}else if(e.shiftKey&&(document.activeElement===a||document.activeElement===sh)){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}}}
  if((e.key==="Enter"||e.key===" ")&&e.target.getAttribute&&e.target.getAttribute("role")==="button"&&!/^(BUTTON|INPUT|TEXTAREA)$/.test(e.target.tagName)){e.preventDefault();e.target.click()}});
async function fotoModal(fid){
  const D=ctx.D,f=D.fotos.find(x=>x.id===fid);if(!f)return;
  const b=await dbGet("blobs",fid);const url=URL.createObjectURL(b.full);
  const its=D.itens.filter(i=>i.ambienteId===f.ambienteId);
  const m=sheet(`<h3>Figura ${ctx.N.foto[fid]||""}</h3><img class="photo-big" src="${url}">
  <div class="mu" style="margin-top:6px">${new Date(f.data).toLocaleString("pt-BR")}${f.lat!=null?` · GPS ${Number(f.lat)}, ${Number(f.lon)}`:" · sem GPS"}</div>
  <label>Legenda</label><textarea id="fLeg" maxlength="${UI_MAX.curto}" aria-label="Legenda" rows="2" placeholder="${esc(legendaFinal(D,{...f,legenda:""}))}">${esc(f.legenda)}</textarea>
  <label for="fIt">Vinculada a</label><select id="fIt"><option value="">Fotos gerais do ambiente</option>${D.medicoes.filter(x=>x.ambienteId===f.ambienteId).map(x=>`<option value="m:${esc(x.id)}" ${f.medicaoId===x.id?"selected":""}>Medição ${esc(x.cod)} – ${esc((x.local||"").slice(0,40))}</option>`).join("")}${its.map(i=>`<option value="${esc(i.id)}" ${f.itemId===i.id&&!f.medicaoId?"selected":""}>Anotação ${esc(ctx.N.item[i.id])} – ${esc((i.texto||"(sem texto)").slice(0,50))}</option>`).join("")}</select>
  <div class="row" style="margin-top:12px"><button class="btn grow" id="fL">◀ Antes</button><button class="btn grow" id="fR">Depois ▶</button></div>
  <div class="row" style="margin-top:8px"><button class="btn d" id="fDel">🗑 Excluir</button><button class="btn p grow" id="fOk">Salvar</button></div>`);
  const close=async()=>{URL.revokeObjectURL(url);m.remove();await rerenderKeepScroll()};
  const salvar=async()=>{const leg=m.querySelector("#fLeg").value.trim(),sel=m.querySelector("#fIt").value||"";const nm=sel.startsWith("m:")?sel.slice(2):null,ni=nm?null:(sel||null);
    const o=await upd("fotos",fid,o=>{o.legenda=leg;if((o.itemId||null)!==ni||(o.medicaoId||null)!==nm){o.itemId=ni;o.medicaoId=nm;o.ordem=ordNow()}});if(o){Object.assign(f,o);alterou(o.estacaoId)}};
  m.querySelector("#fOk").onclick=async()=>{await salvar();await close()};
  m.querySelector("#fDel").onclick=async()=>{if(!confirm("Excluir esta foto?"))return;await enqueue(()=>txRun(["fotos","blobs"],t=>{t.objectStore("fotos").delete(fid);t.objectStore("blobs").delete(fid)}));alterou(f.estacaoId);await close()};
  const grp=x=>(x.itemId||null)===(f.itemId||null)&&(x.medicaoId||null)===(f.medicaoId||null);
  const mover=async dir=>{await salvar();const g=(await dbBy("fotos","ambienteId",f.ambienteId)).filter(grp).sort((a,b)=>a.ordem-b.ordem);
    const i=g.findIndex(x=>x.id===f.id);if(i+dir<0||i+dir>=g.length)return toast("Já está na ponta");
    await moverOrdem("fotos","ambienteId",f.ambienteId,grp,f.id,dir);alterou(f.estacaoId);toast(dir<0?"Movida para antes":"Movida para depois")};
  m.querySelector("#fL").onclick=()=>mover(-1);m.querySelector("#fR").onclick=()=>mover(1);
}
async function addAmbModal(secId){
  const M=await getModelo();if(!ctx.D.secoes.length)return toast("Crie uma etapa primeiro");
  secId=secId||ctx.D.secoes[0].id;
  const m=sheet(`<h3>Adicionar ambientes</h3><label for="aSec">Etapa</label><select id="aSec">${ctx.D.secoes.map(s=>`<option value="${esc(s.id)}" ${s.id===secId?"selected":""}>${esc(s.titulo)}</option>`).join("")}</select>
  <label for="aNomes">Novos ambientes (um por linha)</label><textarea id="aNomes" maxlength="${UI_MAX.txt}" rows="3" placeholder="Ex.:\nPlataforma Via 3 | Plataforma\nSala de baterias | Sala técnica"></textarea><div class="mu">Tipo opcional depois de “|”: ${Object.values(TIPO_CURTO).join(", ")}. Sem tipo, o app deduz pelo nome (dá para trocar no ambiente).</div>
  <label style="margin-top:14px">Da lista-modelo</label><div id="aSug"></div>
  <button class="btn p w" style="margin-top:12px" id="aOk">Adicionar</button>`);
  const sug=()=>{const sid=m.querySelector("#aSec").value,sec=ctx.D.secoes.find(s=>s.id===sid),ex=ctx.D.ambientes.filter(a=>a.secaoId===sid).map(a=>a.nome);
    const l=[...new Set(M.etapas.filter(e=>e.titulo===sec.titulo).flatMap(e=>e.ambientes).concat(M.etapas.filter(e=>e.titulo!==sec.titulo).flatMap(e=>e.ambientes)))].filter(a=>!ex.includes(parseAmbModelo(a).nome));
    m.querySelector("#aSug").innerHTML=l.map(a=>{const p=parseAmbModelo(a);return `<label class="opt" style="margin:0;font-weight:400;color:var(--tx)"><input type="checkbox" value="${esc(a)}"> <span class="grow">${esc(p.nome)}</span><span class="mu">${esc(TIPO_CURTO[p.tipo])}</span></label>`}).join("")||'<div class="mu">Todos já incluídos.</div>'};
  sug();m.querySelector("#aSec").onchange=sug;
  m.querySelector("#aOk").onclick=async()=>{const sid=m.querySelector("#aSec").value;
    const nomes=[...m.querySelectorAll("#aSug input:checked")].map(c=>c.value).concat(m.querySelector("#aNomes").value.split("\n").map(x=>x.trim()).filter(Boolean).map(x=>limitar(x,UI_MAX.curto)));
    if(!nomes.length)return toast("Marque ou digite pelo menos um ambiente");
    const novos=nomes.map(x=>{const p=parseAmbModelo(x);return{id:uid(),estacaoId:ctx.estId,secaoId:sid,nome:p.nome,tipo:p.tipo,geo:null,status:"Pendente",ordem:ordNow()}});
    await enqueue(()=>txRun(["ambientes"],t=>novos.forEach(x=>t.objectStore("ambientes").put(x))));alterou(ctx.estId);
    m.remove();await rerenderKeepScroll();toast(nomes.length+" ambiente(s) adicionado(s)")};
}
function ambMenu(aid){
  const a=ctx.D.ambientes.find(x=>x.id===aid);
  const m=sheet(`<h3>${esc(a.nome)}</h3>
  <div class="opt" data-k="ren">✎ Renomear</div><div class="opt" data-k="dup">⧉ Duplicar (mesmo tipo e geometria, sem medições)</div><div class="opt" data-k="up">↑ Subir</div><div class="opt" data-k="down">↓ Descer</div>
  <div class="opt" data-k="mov">⇄ Mover para outra etapa</div><div class="opt" data-k="del" style="color:var(--red)">🗑 Excluir ambiente e conteúdo</div>`);
  m.querySelectorAll(".opt").forEach(o=>o.onclick=async()=>{const k=o.dataset.k;m.remove();
    if(k==="ren"){const n=prompt("Novo nome:",a.nome);if(n&&n.trim()){const v=limitar(n,UI_MAX.curto);await upd("ambientes",a.id,o=>{o.nome=v});alterou(a.estacaoId)}}
    if(k==="dup"){const n=prompt("Nome do novo ambiente:",a.nome+" 2");if(n&&n.trim()){const v=limitar(n,UI_MAX.curto);await enqueue(()=>dbPut("ambientes",{id:uid(),estacaoId:a.estacaoId,secaoId:a.secaoId,nome:v,tipo:a.tipo,geo:a.geo?{...a.geo}:null,status:"Pendente",ordem:a.ordem+0.5}));alterou(a.estacaoId)}}
    if(k==="up"||k==="down"){await moverOrdem("ambientes","estacaoId",a.estacaoId,x=>x.secaoId===a.secaoId,a.id,k==="up"?-1:1);alterou(a.estacaoId)}
    if(k==="mov"){const outras=ctx.D.secoes.filter(s=>s.id!==a.secaoId);const mm=sheet(`<h3>Mover “${esc(a.nome)}” para</h3>${outras.map(s=>`<div class="opt" data-s="${esc(s.id)}">${esc(s.titulo)}</div>`).join("")}`);
      mm.querySelectorAll(".opt").forEach(x=>x.onclick=async()=>{await upd("ambientes",a.id,o=>{o.secaoId=x.dataset.s;o.ordem=ordNow()});alterou(a.estacaoId);mm.remove();await rerenderKeepScroll()});return}
    if(k==="del"){if(!confirm(`Excluir “${a.nome}” com todas as medições, anotações e fotos?`))return;await delAmbiente(a.id);alterou(a.estacaoId)}
    await rerenderKeepScroll()});
}
