/* ---------- CONFIG ---------- */
async function viewConfig(){
  const M=await getModelo();
  const nGps=(await dbAll("fotos")).filter(f=>f.lat!=null).length;
  const sw=(k,t,d)=>`<label class="opt" style="display:flex;gap:12px;align-items:flex-start;margin:0;padding:12px 0;border-top:1px solid var(--bd);font-weight:400;color:var(--tx)"><input type="checkbox" data-a="opc" data-k="${k}" ${OPC[k]?"checked":""} style="width:24px;height:24px;flex:none;margin-top:2px"><span><b>${t}</b><br><span class="mu">${d}</span></span></label>`;
  app.innerHTML=topbar("Configurações","Catálogo, lista-modelo e textos padrão","#/")+`<main>
  <div class="card"><b>Privacidade e segurança</b><div class="mu" style="margin-bottom:6px">Valem para este aparelho.</div>
  ${sw("ditado","Ditado por voz","No Chrome, o áudio é processado pelos servidores do Google. Desligado, os botões 🎤 somem; o microfone do teclado continua disponível.")}
  ${sw("gps","Registrar GPS nas fotos","Grava latitude/longitude em cada foto (aparece no índice do ZIP de fotos)."+(OPC.gps===null?" Ainda não definido: o app pergunta na primeira foto.":""))}
  <label for="cRes">Resolução das fotos</label><select id="cRes" data-a="opcRes"><option value="1600" ${OPC.resolucao!==2400?"selected":""}>Padrão – 1600 px (≈300 KB/foto)</option><option value="2400" ${OPC.resolucao===2400?"selected":""}>Alta – 2400 px (≈800 KB/foto, mais detalhe para laudo)</option></select>
  <div class="mu" style="margin-top:4px">Vale para fotos novas. As fotos são sempre cópias JPEG geradas pelo app (sem os metadados EXIF do original; data e GPS ficam no próprio app).</div>
  <button class="btn sm d" style="margin-top:8px" data-a="limparGps" ${nGps?"":"disabled"}>Apagar GPS das fotos já registradas (${nGps})</button></div>
  <div class="card"><b>Padrões para novas estações</b><label for="cUn">Unidade (capa)</label><input type="text" id="cUn" maxlength="${UI_MAX.curto}" value="${esc(M.unidade)}">
  <label for="cEq">Equipe técnica padrão (um por linha)</label><textarea id="cEq" maxlength="${UI_MAX.txt}" rows="4" placeholder="Nome - Cargo - Lotação">${esc(M.equipe)}</textarea>
  <label for="cRp">Responsáveis pelo relatório padrão (um por linha: Nome | Cargo | Matrícula/CREA)</label><textarea id="cRp" maxlength="${UI_MAX.txt}" rows="3" placeholder="Victor Lucas | Engenheiro Civil - COIMP/GIOBR | Mat. 0000">${esc(M.responsaveis||"")}</textarea>
  <label for="cOb">Objetivo padrão ({ESTACAO} = nome)</label><textarea id="cOb" maxlength="${UI_MAX.txt}" rows="5">${esc(M.objetivo)}</textarea></div>
  ${catalogoCfgHtml(await cfg("catalogo",null))}
  <h2>Etapas e lista-modelo de ambientes</h2><div class="mu" style="margin:0 4px 8px">Um ambiente por linha, no formato <b>Nome | Tipo</b>. Tipos: ${Object.values(TIPO_CURTO).join(", ")}.</div>
  <div id="cEt">${M.etapas.map((e,i)=>etapaCfg(e,i)).join("")}</div>
  <button class="btn w" data-a="cfgAddEt">＋ Etapa</button>
  <div class="row" style="margin-top:14px"><button class="btn d" data-a="cfgReset">Restaurar padrão</button><button class="btn p grow" data-a="cfgSave">Salvar</button></div>
  <div class="mu" style="margin-top:10px">Vale para estações criadas depois. Estações já existentes são editadas na própria estação.</div></main>`;
}
const etapaCfg=(e,i)=>`<div class="card cfgEt"><label>${i+1}ª Etapa – título<input type="text" class="t" maxlength="${UI_MAX.curto}" value="${esc(e.titulo)}"></label><label>Descrição (método de levantamento)<textarea class="d" maxlength="${UI_MAX.txt}" rows="3">${esc(e.descricao)}</textarea></label><label>Ambientes (um por linha)<textarea class="a" maxlength="${UI_MAX.txt}" rows="8">${esc(e.ambientes.join("\n"))}</textarea></label></div>`;

/* ====================== EVENTOS ====================== */
document.addEventListener("click",async ev=>{
  const el=ev.target.closest("[data-a]");if(!el)return;const a=el.dataset.a,id=el.dataset.id;
  if(["TEXTAREA","INPUT","SELECT"].includes(ev.target.tagName)&&!["ativar","opc"].includes(a))return;
  if(!["cam","gal","go","ativar","foto","restore","ditarIt","medFoto","catImp"].includes(a))await flushSaves();
  if(["respAdd","respDel","addSec","status","novoIt","novoItDitar","itUp","itDown","itDel"].includes(a))alterou(ctx.estId);
  switch(a){
    case "go":ev.stopPropagation();location.hash=el.dataset.h;break;
    case "criarEst":criarEstacao();break;
    case "novaAmbCustom":{const ei=el.dataset.e,inp=$("#nov"+ei),n=inp.value.trim();if(!n)return;$("#lst"+ei).insertAdjacentHTML("beforeend",chkAmb(ei,n));inp.value="";inp.focus();break}
    case "respAdd":{await upd("estacoes",ctx.estId,e=>{e.responsaveis=e.responsaveis||[];e.responsaveis.push({id:uid(),nome:"",cargo:"",registro:""})});await rerenderKeepScroll();const ins=app.querySelectorAll('[data-a=respF][data-k=nome]');ins[ins.length-1]&&ins[ins.length-1].focus();break}
    case "respDel":{if(!confirm("Remover este responsável?"))return;await upd("estacoes",ctx.estId,e=>{e.responsaveis=(e.responsaveis||[]).filter(r=>r.id!==id)});await rerenderKeepScroll();break}
    case "addAmb":addAmbModal(id);break;
    case "ambMenu":ev.stopPropagation();ambMenu(id);break;
    case "secMenu":secMenu(id);break;
    case "addSec":{const n=prompt("Título da nova etapa:");if(n&&n.trim()){await enqueue(()=>dbPut("secoes",{id:uid(),estacaoId:ctx.estId,titulo:limitar(n,UI_MAX.curto),descricao:"",ordem:ordNow()}));await rerenderKeepScroll()}break}
    case "delEst":if(confirm("Excluir a estação inteira com todas as fotos? Isso não pode ser desfeito.")&&prompt('Digite EXCLUIR para confirmar')==="EXCLUIR"){await delEstacao(ctx.estId);location.hash="#/"}break;
    case "status":{const o=await upd("ambientes",ctx.ambId,o=>{o.status=STATUS[(STATUS.indexOf(o.status)+1)%3]});if(!o){toast("Este ambiente não existe mais");location.hash="#/";break}ctx.amb.status=o.status;el.className="chip st-"+o.status;el.textContent=o.status;el.setAttribute("aria-label","Status: "+o.status+". Tocar para alterar");break}
    case "ativar":selecionar(id||"geral");break;
    case "novoIt":case "novoItDitar":{const nid=uid();await enqueue(()=>dbPut("itens",{id:nid,estacaoId:ctx.estId,ambienteId:ctx.ambId,texto:"",ordem:ordNow(),criadoEm:Date.now()}));ctx.ativo=nid;ctx.focar=nid;ctx.ditarAuto=a==="novoItDitar";await marcarLevantado();await render();break}
    case "ditarIt":{ev.stopPropagation();const t=app.querySelector(`textarea[data-id="${id}"]`);ditar(t,null,el);break}
    case "itUp":case "itDown":{ev.stopPropagation();await moverOrdem("itens","ambienteId",ctx.ambId,()=>true,id,a==="itUp"?-1:1);await rerenderKeepScroll();break}
    case "itDel":{ev.stopPropagation();const it=ctx.D.itens.find(x=>x.id===id);const nf=ctx.D.fotos.filter(f=>f.itemId===id).length;if(!confirm(`Excluir esta anotação?${nf?`\nAs ${nf} foto(s) vinculadas passam para “Fotos gerais”.`:""}`))return;
      await enqueue(()=>txRun(["itens","fotos"],t=>{const fo=t.objectStore("fotos"),r=fo.index("ambienteId").getAll(ctx.ambId);r.onsuccess=()=>r.result.filter(f=>f.itemId===id).forEach(f=>{f.itemId=null;fo.put(f)});t.objectStore("itens").delete(it.id)}));if(ctx.ativo===id)ctx.ativo="geral";await rerenderKeepScroll();break}
    case "cam":case "gal":{ev.stopPropagation();ctx.alvo={estacaoId:ctx.estId,ambienteId:ctx.ambId,itemId:id||null,medicaoId:null};selecionar(id||"geral");const inp=$(a==="cam"?"#camIn":"#galIn");inp.value="";inp.click();flushSaves();break}
    case "foto":ev.stopPropagation();fotoModal(id);break;
    case "expDocx":exportDocx();break;
    case "expZip":exportZipFotos();break;
    case "expCsv":exportCsv();break;
    case "backup":backup(null);break;
    case "backupEst":backup(ctx.estId);break;
    case "restore":$("#bkIn").value="";$("#bkIn").click();break;
    case "cfgAddEt":{const d=document.createElement("div");d.innerHTML=etapaCfg({titulo:"",descricao:"",ambientes:[]},$("#cEt").children.length);$("#cEt").appendChild(d.firstChild);break}
    case "opc":{OPC[el.dataset.k]=el.checked;await enqueue(()=>setCfg("opcoes",{...OPC}));if(el.dataset.k==="gps"&&!el.checked){geoStop();lastPos=null}toast((el.dataset.k==="gps"?"GPS ":"Ditado ")+(el.checked?"ligado":"desligado"));break}
    case "limparGps":{const fs=(await dbAll("fotos")).filter(f=>f.lat!=null);if(!fs.length||!confirm(`Apagar as coordenadas de ${fs.length} foto(s)? Não dá para desfazer.`))return;await enqueue(()=>txRun(["fotos"],t=>{const os=t.objectStore("fotos");fs.forEach(f=>{f.lat=null;f.lon=null;os.put(f)})}));new Set(fs.map(f=>f.estacaoId)).forEach(alterou);toast("GPS apagado");render();break}
    case "cfgReset":if(confirm("Restaurar lista-modelo e textos padrão?")){await enqueue(()=>dbDel("config","modelo"));render();toast("Padrão restaurado")}break;
    default:if(QA[a])await QA[a](el,ev,id);break;
    case "cfgSave":{const M=await getModelo();M.unidade=$("#cUn").value.trim();M.equipe=$("#cEq").value.trim();M.responsaveis=$("#cRp").value.trim();M.objetivo=$("#cOb").value.trim();
      M.etapas=[...document.querySelectorAll(".cfgEt")].map(c=>({titulo:c.querySelector(".t").value.trim(),descricao:c.querySelector(".d").value.trim(),ambientes:c.querySelector(".a").value.split("\n").map(s=>s.trim()).filter(Boolean).map(x=>x.slice(0,UI_MAX.curto))})).filter(e=>e.titulo);
      await enqueue(()=>setCfg("modelo",M));toast("Configurações salvas");break}
  }
});
const salvarItem=(id,v)=>deb("it"+id,()=>updRaw("itens",id,o=>{o.texto=v}).then(()=>{const x=ctx.D&&ctx.D.itens.find(i=>i.id===id);if(x)x.texto=v}));
const salvarEst=(k,v)=>{const eid=ctx.estId;deb("est"+eid+k,()=>updRaw("estacoes",eid,e=>{e[k]=v}))};
const salvarSec=(id,v)=>deb("sec"+id,()=>updRaw("secoes",id,o=>{o.descricao=v}));
const salvarResp=(rid,k,v)=>{const eid=ctx.estId;deb("resp"+rid+k,()=>updRaw("estacoes",eid,e=>{const r=(e.responsaveis||[]).find(x=>x.id===rid);if(!r)return false;r[k]=v}),300)};
async function marcarLevantado(){if(ctx.amb&&ctx.amb.status==="Pendente"){const o=await upd("ambientes",ctx.ambId,o=>{if(o.status!=="Pendente")return false;o.status="Levantado"});if(o)ctx.amb.status=o.status}}
/* grava o que estiver pendente ao sair/minimizar o app */
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden")flushSaves()});
window.addEventListener("pagehide",()=>flushSaves());
document.addEventListener("input",ev=>{const el=ev.target,a=el.dataset.a;
  if(["itTxt","estField","secDesc","respF"].includes(a))alterou(ctx.estId);
  if(a==="itTxt")salvarItem(el.dataset.id,el.value);
  if(a==="estField")salvarEst(el.dataset.k,el.value);
  if(a==="secDesc")salvarSec(el.dataset.id,el.value);
  if(a==="respF")salvarResp(el.dataset.rid,el.dataset.k,el.value);
});
document.addEventListener("change",async ev=>{const el=ev.target;if(el.dataset.a==="opcRes"){OPC.resolucao=+el.value;await enqueue(()=>setCfg("opcoes",{...OPC}));toast("Resolução: "+el.value+" px")}});
document.addEventListener("focusin",ev=>{const el=ev.target;if(el.dataset.a==="itTxt"){const c=el.closest("[data-a=ativar]");if(c)c.click()}});
const onFiles=async ev=>{const files=[...ev.target.files];if(!files.length||!ctx.alvo)return;await addFotos(files,ctx.alvo);
  alterou(ctx.alvo.estacaoId);await marcarLevantado();await rerenderKeepScroll()};
$("#camIn").addEventListener("change",onFiles);$("#galIn").addEventListener("change",onFiles);
$("#bkIn").addEventListener("change",ev=>{const f=ev.target.files[0];if(f)restore(f)});

