const X=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,"");
function R(t,o={}){
  const rp=(o.font?`<w:rFonts w:ascii="${o.font}" w:hAnsi="${o.font}" w:cs="${o.font}" w:eastAsia="${o.font}"/>`:"")+(o.b?"<w:b/><w:bCs/>":"")+(o.i?"<w:i/><w:iCs/>":"")+`<w:color w:val="${o.color||"262626"}"/><w:sz w:val="${o.sz||24}"/><w:szCs w:val="${o.sz||24}"/>`;
  return String(t).split("\n").map((ln,i)=>(i?`<w:r><w:rPr>${rp}</w:rPr><w:br/></w:r>`:"")+`<w:r><w:rPr>${rp}</w:rPr><w:t xml:space="preserve">${X(ln)}</w:t></w:r>`).join("");
}
function Pa(runs,o={}){
  const pp=(o.style?`<w:pStyle w:val="${o.style}"/>`:"")+(o.keepNext?"<w:keepNext/>":"")+(o.pageBreak?"<w:pageBreakBefore/>":"")+(o.numId?`<w:numPr><w:ilvl w:val="0"/><w:numId w:val="${o.numId}"/></w:numPr>`:"")+
    `<w:spacing w:before="${o.before??0}" w:after="${o.after??200}" w:line="276" w:lineRule="auto"/>`+`<w:ind w:left="${o.left??360}" w:right="${o.right??330}" ${o.hanging?`w:hanging="${o.hanging}"`:'w:firstLine="0"'}/>`+`<w:jc w:val="${o.jc||"both"}"/>`;
  return `<w:p><w:pPr>${pp}</w:pPr>${runs}</w:p>`;
}
const H1=(t,o={})=>Pa(R(t,{sz:28,b:true}),{style:"Heading1",before:o.before??240,after:200,keepNext:true,pageBreak:o.pageBreak,jc:"left"});
const H2=t=>Pa(R(t,{sz:24,b:true}),{style:"Heading2",before:240,after:160,keepNext:true,jc:"left",left:360});
const PB=()=>`<w:p><w:r><w:br w:type="page"/></w:r></w:p>`;
const EMU=914400;
function imgRun(rid,docId,wEmu,hEmu,name){
  return `<w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${wEmu}" cy="${hEmu}"/><wp:effectExtent l="0" t="0" r="0" b="0"/><wp:docPr id="${docId}" name="${name}"/><wp:cNvGraphicFramePr><a:graphicFrameLocks noChangeAspect="1"/></wp:cNvGraphicFramePr><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="${docId}" name="${name}"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="${rid}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${wEmu}" cy="${hEmu}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r>`;
}
function figTable(cells){
  const bd=`<w:top w:val="single" w:sz="8" w:space="0" w:color="000000"/><w:left w:val="single" w:sz="8" w:space="0" w:color="000000"/><w:bottom w:val="single" w:sz="8" w:space="0" w:color="000000"/><w:right w:val="single" w:sz="8" w:space="0" w:color="000000"/><w:insideH w:val="single" w:sz="8" w:space="0" w:color="000000"/><w:insideV w:val="single" w:sz="8" w:space="0" w:color="000000"/>`;
  const W=5032;let rows="";
  for(let i=0;i<cells.length;i+=2){
    const tc=c=>`<w:tc><w:tcPr><w:tcW w:w="${W}" w:type="dxa"/><w:tcMar><w:top w:w="100" w:type="dxa"/><w:left w:w="100" w:type="dxa"/><w:bottom w:w="100" w:type="dxa"/><w:right w:w="100" w:type="dxa"/></w:tcMar><w:vAlign w:val="bottom"/></w:tcPr>${c||Pa("",{left:0,right:0,after:0})}</w:tc>`;
    rows+=`<w:tr><w:trPr><w:cantSplit/></w:trPr>${tc(cells[i])}${tc(cells[i+1])}</w:tr>`;
  }
  return `<w:tbl><w:tblPr><w:tblW w:w="${W*2}" w:type="dxa"/><w:tblInd w:w="366" w:type="dxa"/><w:tblBorders>${bd}</w:tblBorders><w:tblLayout w:type="fixed"/><w:tblLook w:val="0000"/></w:tblPr><w:tblGrid><w:gridCol w:w="${W}"/><w:gridCol w:w="${W}"/></w:tblGrid>${rows}</w:tbl>`+Pa("",{after:120});
}
function textoParas(txt,o={}){
  const blocos=String(txt||"").replace(/\r/g,"").split(/\n\s*\n/).map(s=>s.trim()).filter(Boolean);
  return blocos.map(bl=>{
    const linhas=bl.split("\n");
    if(linhas.every(l=>/^\s*\d+[.)]\s+/.test(l)))return linhas.map(l=>{const m=l.match(/^\s*(\d+[.)])\s+(.*)$/);return Pa(R(m[1]+" ",{b:true})+R(m[2]),{left:1080,hanging:360,after:120})}).join("");
    return Pa(R(bl),o);
  }).join("");
}
function itemParas(num,txt){
  const ls=String(txt||"").replace(/\r/g,"").split("\n").map(s=>s.trim()).filter(Boolean);
  if(!ls.length)ls.push("");
  return ls.map((l,i)=>Pa((i===0?R(num+" ",{b:true}):"")+R(l),{left:360,right:556,after:i===ls.length-1?200:80})).join("");
}

async function exportDocx(){
  await flushSaves();
  const D=await loadEst(ctx.estId);if(!await avisoVolume(D,"Relatório"))return;const N=numerar(D);const e=D.est;
  if(!N.ultimaSecao&&!confirm("Nenhum ambiente tem anotações ou fotos. Gerar mesmo assim?"))return;
  const b=busy("Montando relatório…");
  try{
    const zip=await JSZip.loadAsync(b64ToU8(TEMPLATE_B64));
    const NOME="Estação "+e.nome;const NOMEU=NOME.toUpperCase();
    const rels=[["rIdSt","styles","styles.xml"],["rIdSe","settings","settings.xml"],["rIdFt","fontTable","fontTable.xml"],["rIdNu","numbering","numbering.xml"],["rIdTh","theme","theme/theme1.xml"],["rIdH1","header","header1.xml"],["rIdH2","header","header2.xml"],["rIdF1","footer","footer1.xml"],["rIdF2","footer","footer2.xml"],["rIdCov","image","media/cover.jpg"]];
    let docId=10;
    const capa=`<w:p><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr><w:r><w:drawing><wp:anchor distT="0" distB="0" distL="0" distR="0" simplePos="0" relativeHeight="0" behindDoc="1" locked="1" layoutInCell="1" allowOverlap="1"><wp:simplePos x="0" y="0"/><wp:positionH relativeFrom="page"><wp:posOffset>0</wp:posOffset></wp:positionH><wp:positionV relativeFrom="page"><wp:posOffset>0</wp:posOffset></wp:positionV><wp:extent cx="7560000" cy="10692000"/><wp:effectExtent l="0" t="0" r="0" b="0"/><wp:wrapNone/><wp:docPr id="1" name="Capa"/><wp:cNvGraphicFramePr/><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="1" name="cover.jpg"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rIdCov"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="7560000" cy="10692000"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:anchor></w:drawing></w:r></w:p>`+
      Pa(R("RELATÓRIO DE VISTORIA TÉCNICA",{sz:50,font:"Libre Franklin"}),{before:300,after:120,left:360,jc:"left"})+
      Pa(R(NOMEU,{sz:50,font:"Libre Franklin",color:"92D050",b:true}),{after:240,left:360,jc:"left"})+
      Pa(R(e.unidade||"",{sz:20,font:"Libre Franklin"}),{after:80,left:360,jc:"left"})+
      Pa(R(e.datas||"",{sz:24,font:"Libre Franklin",color:"595959"}),{after:0,left:360,jc:"left"});
    const linha=e.linha?" da "+e.linha:"";
    const resp=(e.responsaveis||[]).filter(r=>(r.nome||"").trim());
    const apres=PB()+Pa("",{before:2400})+Pa(R("RELATÓRIO DE VISTORIA TÉCNICA",{b:true}),{jc:"center",after:600})+Pa(R(NOMEU,{b:true}),{jc:"center",after:1200})+
      Pa(R(`Apresentação das condições atuais da ${NOME}${linha} da CBTU STU-REC.`,{b:true}),{jc:"center",left:720,right:720})+
      Pa(R(`Este relatório visa apresentar as atividades realizadas e fornecer as informações levantadas durante a realização das vistorias técnicas na ${NOME} da Superintendência de Trens Urbanos do Recife.`,{b:true}),{jc:"center",left:720,right:720})+
      (resp.length?Pa(R("RESPONSÁVEIS PELO RELATÓRIO",{b:true,sz:22}),{jc:"center",before:1200,after:200})+resp.map(r=>Pa(R(r.nome,{b:true,sz:22}),{jc:"center",after:0})+Pa(R([r.cargo,r.registro].filter(Boolean).join(" – "),{sz:20,color:"595959"}),{jc:"center",after:160})).join(""):"");
    // seções do corpo
    const titulos=[];let body="";
    const sec=(t,o)=>{titulos.push(t);return H1(t,o)};
    body+=sec("1. OBJETIVO DA VISTORIA",{pageBreak:true,before:0})+textoParas((e.objetivo||"").replaceAll("{ESTACAO}",NOME));
    body+=sec("2. LOCALIZAÇÃO")+(textoParas(e.localizacao)||Pa(R("[Descrever a localização da estação.]",{color:"C00000"})));
    const equipe=String(e.equipe||"").split("\n").map(s=>s.trim()).filter(Boolean);
    body+=sec("3. DATA E EQUIPE")+Pa(R("A vistoria foi realizada em ")+R(e.datas||hoje(),{b:true})+R("."))+Pa(R("Equipe Técnica:"),{after:120})+equipe.map(x=>Pa(R(x),{after:80})).join("")+Pa("",{after:0});
    const secsUsadas=D.secoes.filter(s=>N.sec[s.id]);
    body+=sec("4. MÉTODO DE LEVANTAMENTO",{pageBreak:true,before:0})+textoParas(e.metodoIntro)+
      secsUsadas.map((s,i)=>Pa(R(`${i+1}ª Etapa – ${s.titulo}`,{b:true})+R(s.descricao?": "+s.descricao:""),{left:1080,hanging:360,after:160})).join("")+textoParas(e.metodoFim);
    // figuras
    let figXml=[];
    for(const s of secsUsadas){
      body+=sec(`${N.sec[s.id]}. ${s.titulo.toUpperCase()}`,{pageBreak:true,before:0});
      for(const a of D.ambientes.filter(x=>x.secaoId===s.id&&N.amb[x.id])){
        body+=H2(`${N.amb[a.id]} ${a.nome.toUpperCase()}`);
        for(const it of D.itens.filter(i=>i.ambienteId===a.id))body+=itemParas(N.item[it.id],it.texto);
        const fs=fotosOrdenadas(D,a.id);
        if(fs.length){
          const cells=[];
          for(const f of fs){
            const n=N.foto[f.id];b.set(`Inserindo figura ${n} de ${N.ordemFotos.length}…`);
            const br=await dbGet("blobs",f.id);if(!br||!br.full)throw new Error(`a figura ${n} está sem arquivo de imagem`);const blob=br.full;const fn=`media/foto${n}.jpg`;zip.file("word/"+fn,blob,{compression:"STORE"});
            const rid="rIdF"+n+"x";rels.push([rid,"image",fn]);
            const maxW=3.05*EMU,maxH=3.4*EMU,sc=Math.min(maxW/f.w,maxH/f.h);const w=Math.round(f.w*sc),h=Math.round(f.h*sc);
            cells.push(Pa(imgRun(rid,++docId,w,h,"Figura "+n),{jc:"center",left:0,right:0,after:80})+Pa(R(`Figura ${n}: ${legendaFinal(D,f)}`,{i:true,sz:20}),{jc:"left",left:0,right:0,after:0}));
          }
          body+=figTable(cells);
        }
      }
    }
    let n=N.ultimaSecao;
    if((e.comunicacao||"").trim())body+=sec(`${++n}. COMUNICAÇÃO VISUAL`,{pageBreak:true,before:0})+textoParas(e.comunicacao);
    body+=sec(`${++n}. CONCLUSÃO`,{pageBreak:!(e.comunicacao||"").trim(),before:(e.comunicacao||"").trim()?360:0})+(textoParas(e.conclusao)||Pa(R("[Redigir a conclusão.]",{color:"C00000"})));
    const anexos=String(e.anexos||"").split("\n").map(s=>s.trim()).filter(Boolean);
    body+=sec(`${++n}. ANEXOS`)+(anexos.length?anexos.map((x,i)=>Pa(R(`${i+1}. `,{b:true})+R(x),{left:1080,hanging:360,after:80})).join(""):Pa(R("Não há.")));
    const linhaAss=Pa("",{before:600,after:0})+Pa(R("_______________________________________"),{jc:"center",after:0});
    let assXml;
    if(String(e.assinaturas||"").trim())assXml=String(e.assinaturas).split("\n").map(s=>s.trim()).filter(Boolean).map(x=>linhaAss+Pa(R(x,{sz:22}),{jc:"center",after:120})).join("");
    else if(resp.length)assXml=resp.map(r=>linhaAss+Pa(R(r.nome,{b:true,sz:22}),{jc:"center",after:0})+[r.cargo,r.registro].filter(Boolean).map(x=>Pa(R(x,{sz:20}),{jc:"center",after:0})).join("")+Pa("",{after:120})).join("");
    else assXml=equipe.map(x=>linhaAss+Pa(R(x,{sz:22}),{jc:"center",after:120})).join("");
    body+=sec(`${++n}. ASSINATURAS`,{before:480})+assXml;
    // sumário
    const sumario=PB()+Pa(R("SUMÁRIO",{b:true}),{before:600,after:400,left:360,jc:"left"})+
      `<w:p><w:pPr><w:spacing w:after="0"/></w:pPr><w:r><w:fldChar w:fldCharType="begin" w:dirty="true"/></w:r><w:r><w:instrText xml:space="preserve"> TOC \\o "1-1" \\h \\z \\u </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>`+
      titulos.map(t=>Pa(R(t,{b:true,sz:22}),{after:120,left:360,jc:"left"})).join("")+`<w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>`;
    const sect=`<w:sectPr><w:headerReference w:type="default" r:id="rIdH1"/><w:headerReference w:type="first" r:id="rIdH2"/><w:footerReference w:type="default" r:id="rIdF1"/><w:footerReference w:type="first" r:id="rIdF2"/><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="720" w:right="424" w:bottom="720" w:left="720" w:header="708" w:footer="708" w:gutter="0"/><w:pgNumType w:start="0"/><w:titlePg/></w:sectPr>`;
    const doc=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:body>${capa}${apres}${sumario}${body}${sect}</w:body></w:document>`;
    const T="http://schemas.openxmlformats.org/officeDocument/2006/relationships/";
    zip.file("word/document.xml",doc);
    zip.file("word/_rels/document.xml.rels",`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${rels.map(([i,t,g])=>`<Relationship Id="${i}" Type="${T}${t}" Target="${g}"/>`).join("")}</Relationships>`);
    zip.file("docProps/core.xml",`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>${X("Relatório de Vistoria Técnica – "+NOME)}</dc:title><dc:creator>Quantitativos de Campo</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">${new Date().toISOString().slice(0,19)}Z</dcterms:created></cp:coreProperties>`);
    b.set("Compactando arquivo…");
    const out=await zip.generateAsync({type:"blob",mimeType:"application/vnd.openxmlformats-officedocument.wordprocessingml.document",compression:"DEFLATE"});
    b.close();
    await saveFile(out,`Relatorio_Vistoria_${slug(e.nome)}_${new Date().toISOString().slice(0,10)}.docx`);
  }catch(err){b.close();console.error(err);alert("Erro ao gerar relatório: "+err.message)}
}

/* ====================== OUTRAS EXPORTAÇÕES ====================== */
const csvCel=v=>{let t=String(v??"");if(typeof v!=="number"&&/^[=+\-@\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'};
async function exportZipFotos(){
  await flushSaves();
  const D=await loadEst(ctx.estId);if(!await avisoVolume(D,"ZIP de fotos"))return;const N=numerar(D);if(!N.ordemFotos.length)return toast("Nenhuma foto nesta estação");
  const b=busy("Preparando fotos…");
  try{
    const zip=new JSZip();const E=slug(D.est.nome);const rows=[["Figura","Arquivo","Etapa","Ambiente","Item","Legenda","Data/hora","Latitude","Longitude"]];
    for(const f of N.ordemFotos){
      const n=N.foto[f.id],a=D.ambientes.find(x=>x.id===f.ambienteId),s=D.secoes.find(x=>x.id===a.secaoId);
      const nome=`${E}_${N.amb[a.id]}_${slug(a.nome)}_${String(n).padStart(3,"0")}.jpg`;
      const br=await dbGet("blobs",f.id);if(!br||!br.full)throw new Error(`a figura ${n} está sem arquivo de imagem`);zip.file(nome,br.full,{compression:"STORE"});
      rows.push([n,nome,s?s.titulo:"",a.nome,f.itemId?N.item[f.itemId]||"":"",legendaFinal(D,f),new Date(f.data).toLocaleString("pt-BR"),f.lat??"",f.lon??""]);
    }
    zip.file("indice_fotos.csv","﻿"+rows.map(r=>r.map(csvCel).join(";")).join("\r\n"));
    const out=await zip.generateAsync({type:"blob"});b.close();await saveFile(out,`Fotos_${E}.zip`);
  }catch(err){b.close();alert("Erro: "+err.message)}
}
async function exportCsv(){
  const D=await loadEst(ctx.estId);const N=numerar(D);
  const rows=[["Estação","Etapa","Nº ambiente","Ambiente","Status","Nº item","Texto","Figuras"]];
  for(const s of D.secoes)for(const a of D.ambientes.filter(x=>x.secaoId===s.id)){
    const its=D.itens.filter(i=>i.ambienteId===a.id);
    if(!its.length)rows.push([D.est.nome,s.titulo,N.amb[a.id]||"",a.nome,a.status,"","",fotosOrdenadas(D,a.id).map(f=>N.foto[f.id]).join(", ")]);
    for(const it of its)rows.push([D.est.nome,s.titulo,N.amb[a.id]||"",a.nome,a.status,N.item[it.id]||"",it.texto,D.fotos.filter(f=>f.itemId===it.id).map(f=>N.foto[f.id]).join(", ")]);
  }
  await saveFile(new Blob(["﻿"+rows.map(r=>r.map(csvCel).join(";")).join("\r\n")],{type:"text/csv"}),`Levantamento_${slug(D.est.nome)}.csv`);
}

/* ====================== BACKUP / RESTAURAÇÃO ====================== */
/* lê o índice (End Of Central Directory) no fim do ZIP gerado: conta as entradas sem carregar o arquivo inteiro */
async function entradasZip(blob){
  const tam=Math.min(blob.size,66000),buf=new DataView(await blob.slice(blob.size-tam).arrayBuffer());
  for(let i=tam-22;i>=0;i--)if(buf.getUint32(i,true)===0x06054b50){const total=buf.getUint16(i+10,true),cdTam=buf.getUint32(i+12,true),cdOff=buf.getUint32(i+16,true);
    if(cdOff+cdTam>blob.size)throw new Error("índice do ZIP inconsistente");return total}
  throw new Error("índice do ZIP não encontrado")}
const CRC_T=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
function crc32(u8){let c=0xFFFFFFFF;for(let i=0;i<u8.length;i++)c=CRC_T[(c^u8[i])&0xFF]^(c>>>8);return (c^0xFFFFFFFF)>>>0}
async function backup(estId){
  await flushSaves();
  {const fs=estId?await dbBy("fotos","estacaoId",estId):await dbAll("fotos");let mb=0;for(const f of fs)mb+=(f.bytes||350000)*1.1/1048576;
    if(mb>150&&!confirm(`O backup ${estId?"desta estação":"completo"} terá ~${mb.toFixed(0)} MB, montados na memória do celular. Em aparelhos com pouca RAM o app pode fechar.${estId?"":"\n\nRecomendado: backup por estação (aba Exportar de cada estação), que é menor."}\n\nContinuar mesmo assim?`))return}
  const t0=Date.now();
  const b=busy("Gerando backup…");
  try{
    const all=async n=>estId?(n==="estacoes"?[await dbGet("estacoes",estId)]:await dbBy(n,"estacaoId",estId)):await dbAll(n);
    const data={app:"quantitativos-campo",formato:1,versao:VERSAO,geradoEm:new Date().toISOString(),estacoes:await all("estacoes"),secoes:await all("secoes"),ambientes:await all("ambientes"),servicos:await all("servicos"),itens:await all("itens"),medicoes:await all("medicoes"),fotos:await all("fotos"),
      config:estId?[]:(await dbAll("config")).filter(c=>c.key==="modelo"||c.key==="opcoes"||c.key==="catalogo")};
    // 1) nenhuma foto pode estar sem arquivo
    const faltando=[];const zip=new JSZip();
    let i=0;for(const f of data.fotos){i++;if(i%10===0)b.set(`Conferindo fotos ${i}/${data.fotos.length}…`);
      const r=await dbGet("blobs",f.id);if(!r||!r.full||!r.full.size){faltando.push(f);continue}
      zip.file(`fotos/${f.id}.jpg`,r.full,{compression:"STORE"});zip.file(`thumbs/${f.id}.jpg`,r.thumb||r.full,{compression:"STORE"})}
    if(faltando.length){b.close();
      const ambs=await dbAll("ambientes"),ests=await dbAll("estacoes");
      const onde=faltando.map(f=>{const a=ambs.find(x=>x.id===f.ambienteId),e=ests.find(x=>x.id===f.estacaoId);return `• ${e?e.nome:"?"} › ${a?a.nome:"?"} (foto de ${new Date(f.data).toLocaleString("pt-BR")})`}).slice(0,15).join("\n");
      if(!confirm(`Backup interrompido: ${faltando.length} foto(s) estão registradas mas sem a imagem no aparelho:\n\n${onde}\n\nOK = remover esses registros vazios e gerar o backup · Cancelar = não fazer nada`))return;
      const ids=faltando.map(f=>f.id);await enqueue(()=>txRun(["fotos","blobs"],t=>ids.forEach(id=>{t.objectStore("fotos").delete(id);t.objectStore("blobs").delete(id)})));
      toast(ids.length+" registro(s) vazio(s) removido(s)");return backup(estId)}
    zip.file("dados.json",JSON.stringify(data));
    b.set("Compactando…");
    const out=await zip.generateAsync({type:"blob",streamFiles:true});
    // 2) conferência do arquivo gerado. Até 120 MB reabre o ZIP inteiro; acima disso confere só o índice
    //    (reabrir dobraria o uso de memória e poderia derrubar o app em celulares com pouca RAM)
    b.set("Conferindo o arquivo gerado…");
    if(!out||!out.size)throw new Error("arquivo vazio");
    if(out.size<=120*1048576){
      const chk=await JSZip.loadAsync(out);const d2=JSON.parse(await chk.file("dados.json").async("string"));
      const nFotos=Object.keys(chk.files).filter(k=>/^fotos\/.+\.jpg$/.test(k)).length;
      if(d2.fotos.length!==data.fotos.length||nFotos!==data.fotos.length||d2.estacoes.length!==data.estacoes.length)throw new Error("o arquivo gerado não confere com os dados");
    }else{const n=await entradasZip(out),esperado=Object.keys(zip.files).length;
      if(n!==esperado)throw new Error(`o arquivo gerado não confere (${n} de ${esperado} arquivos no índice do ZIP)`)}
    b.close();
    const nome=estId?`Backup_${slug(data.estacoes[0].nome)}_${new Date().toISOString().slice(0,10)}.zip`:`Backup_Quantitativos_${new Date().toISOString().slice(0,16).replace(/[:T]/g,"-")}.zip`;
    const saiu=await saveFile(out,nome);
    if(!saiu){toast("Backup não foi baixado nem compartilhado",4000);return}
    // 3) o navegador não confirma que o arquivo foi guardado: pergunta ao usuário
    if(confirm(`Backup gerado e conferido (${data.estacoes.length} estação(ões), ${data.fotos.length} fotos).\n\nVocê guardou o arquivo FORA deste celular (computador, pasta da rede, e-mail institucional)?\n\nOK = sim, já guardei · Cancelar = ainda não`)){
      await enqueue(()=>setCfg(estId?"ultimoBackupEst_"+estId:"ultimoBackup",t0));toast("Backup registrado")}
    else toast("Backup gerado, mas não registrado como guardado",3500);
  }catch(err){b.close();alert("Erro no backup: "+err.message+"\nNenhum backup válido foi registrado.")}
}

/* ---------- validação de backup (nada importado é confiável) ----------
   Limites folgados e alinhados aos campos da tela (maxlength): o app nunca gera um backup que ele mesmo recuse.
   Registro inválido NÃO derruba o backup inteiro: é descartado (com seus dependentes) e listado para o usuário decidir. */
const RX_ID=/^[a-z0-9]{6,40}$/;
const LIM={txt:1000000,curto:2000};
const UI_MAX={txt:100000,curto:500};
function validarBackup(data){
  if(!data||typeof data!=="object"||data.app!=="quantitativos-campo")throw new Error(data&&data.app==="levantamento-campo"?"Este é um backup do app de Levantamento (v1.x), não do app de Quantitativos.":"Arquivo não é um backup deste app.");
  for(const k of ["estacoes","secoes","ambientes","servicos","itens","medicoes","fotos"])if(!Array.isArray(data[k]))throw new Error("Backup sem a lista '"+k+"'.");
  const prob=[];const P=m=>{if(prob.length<200)prob.push(m)};
  const obj=x=>x&&typeof x==="object"&&!Array.isArray(x);
  const txt=(v,max=LIM.txt)=>v==null?"":(typeof v==="string"&&v.length<=max?v:null);
  const num=v=>typeof v==="number"&&isFinite(v);
  const ids=new Set();const idOk=id=>typeof id==="string"&&RX_ID.test(id)&&!ids.has(id);
  const out={estacoes:[],secoes:[],ambientes:[],servicos:[],itens:[],medicoes:[],fotos:[],config:[]};
  const est={},sec={},amb={},itm={},svc={},med={};
  const CAMPOS_EST=["linha","localizacao","datas","equipe","unidade","objetivo","metodoIntro","metodoFim","comunicacao","conclusao","anexos","assinaturas"];
  data.estacoes.forEach((e,n)=>{
    if(!obj(e)||!idOk(e.id)){P(`Estação nº ${n+1}: registro inválido (descartada com todo o conteúdo)`);return}
    const nome=txt(e.nome,LIM.curto);if(!nome||!nome.trim()){P(`Estação nº ${n+1}: sem nome válido (descartada)`);return}
    const o={id:e.id,nome,criadoEm:num(e.criadoEm)?e.criadoEm:Date.now(),responsaveis:[]};
    for(const k of CAMPOS_EST){const v=txt(e[k]);if(v===null){P(`Estação ${nome}: campo “${k}” inválido (deixado em branco)`);o[k]=""}else o[k]=v}
    (Array.isArray(e.responsaveis)?e.responsaveis:[]).forEach(r=>{
      if(!obj(r)||typeof r.id!=="string"||!RX_ID.test(r.id)){P(`Estação ${nome}: responsável inválido (descartado)`);return}
      const nm=txt(r.nome,LIM.curto),cg=txt(r.cargo,LIM.curto),rg=txt(r.registro,LIM.curto);
      if(nm===null||cg===null||rg===null){P(`Estação ${nome}: responsável inválido (descartado)`);return}
      o.responsaveis.push({id:r.id,nome:nm,cargo:cg,registro:rg})});
    ids.add(e.id);est[e.id]=o;out.estacoes.push(o)});
  data.secoes.forEach((x,n)=>{
    if(!obj(x)||!idOk(x.id)||!est[x.estacaoId]){P(`Etapa nº ${n+1}: inválida ou de estação descartada`);return}
    const t=txt(x.titulo,LIM.curto),d=txt(x.descricao);if(!t||d===null){P(`Etapa nº ${n+1} (${est[x.estacaoId].nome}): campos inválidos (descartada)`);return}
    const o={id:x.id,estacaoId:x.estacaoId,titulo:t,descricao:d,ordem:num(x.ordem)?x.ordem:n};ids.add(x.id);sec[x.id]=o;out.secoes.push(o)});
  data.ambientes.forEach((x,n)=>{
    if(!obj(x)||!idOk(x.id)||!sec[x.secaoId]||sec[x.secaoId].estacaoId!==x.estacaoId){P(`Ambiente nº ${n+1}: inválido ou de etapa descartada`);return}
    const nm=txt(x.nome,LIM.curto);if(!nm){P(`Ambiente nº ${n+1}: nome ausente ou com mais de ${LIM.curto} caracteres (descartado)`);return}
    let stt=x.status;if(!STATUS.includes(stt)){P(`Ambiente ${nm}: status inválido (ajustado para Pendente)`);stt="Pendente"}
    let tp=x.tipo;if(!TIPOS[tp]){if(tp!=null)P(`Ambiente ${nm}: tipo inválido (deduzido pelo nome)`);tp=inferTipo(nm)}
    let geo=null;if(obj(x.geo)){geo={};for(const k of ["piso","perim","pd","vaos"]){const v=x.geo[k];if(v==null||v==="")continue;if((typeof v==="string"&&v.length<=20)||num(v))geo[k]=String(v);else P(`Ambiente ${nm}: geometria “${k}” inválida (ignorada)`)}}
    const o={id:x.id,estacaoId:x.estacaoId,secaoId:x.secaoId,nome:nm,tipo:tp,geo,status:stt,ordem:num(x.ordem)?x.ordem:n};ids.add(x.id);amb[x.id]=o;out.ambientes.push(o)});
  const RX_COD=/^\d{1,3}(\.\d{1,3}){0,3}$/;
  data.servicos.forEach((x,n)=>{
    if(!obj(x)||!idOk(x.id)||!amb[x.ambienteId]||amb[x.ambienteId].estacaoId!==x.estacaoId){P(`Serviço nº ${n+1}: inválido ou de ambiente descartado`);return}
    if(typeof x.cod!=="string"||!RX_COD.test(x.cod)){P(`Serviço em “${amb[x.ambienteId].nome}”: item inválido (descartado)`);return}
    if(Object.values(svc).some(s=>s.ambienteId===x.ambienteId&&s.cod===x.cod)){P(`Serviço ${x.cod} repetido em “${amb[x.ambienteId].nome}” (descartado)`);return}
    let es=x.estado||"";if(!(es===""||ESTADOS[es])){P(`Serviço ${x.cod} em “${amb[x.ambienteId].nome}”: situação inválida (deixada sem verificar)`);es=""}
    const o={id:x.id,estacaoId:x.estacaoId,ambienteId:x.ambienteId,cod:x.cod,estado:es,extra:x.extra===true,ordem:num(x.ordem)?x.ordem:n};ids.add(x.id);svc[x.id]=o;out.servicos.push(o)});
  data.itens.forEach((x,n)=>{
    if(!obj(x)||!idOk(x.id)||!amb[x.ambienteId]||amb[x.ambienteId].estacaoId!==x.estacaoId){P(`Anotação nº ${n+1}: inválida ou de ambiente descartado`);return}
    const t=txt(x.texto);if(t===null){P(`Anotação em “${amb[x.ambienteId].nome}”: texto inválido (descartada)`);return}
    const o={id:x.id,estacaoId:x.estacaoId,ambienteId:x.ambienteId,texto:t,ordem:num(x.ordem)?x.ordem:n,criadoEm:num(x.criadoEm)?x.criadoEm:Date.now()};ids.add(x.id);itm[x.id]=o;out.itens.push(o)});
  data.medicoes.forEach((x,n)=>{
    if(!obj(x)||!idOk(x.id)||!svc[x.servicoId]||svc[x.servicoId].ambienteId!==x.ambienteId||svc[x.servicoId].estacaoId!==x.estacaoId||svc[x.servicoId].cod!==x.cod){P(`Medição nº ${n+1}: inválida ou de serviço descartado`);return}
    const onde=amb[x.ambienteId].nome;const e={};
    if(obj(x.e))for(const k of MED_CAMPOS){const v=x.e[k];if(v==null)continue;if(typeof v==="string"&&v.length<=40)e[k]=v;else if(num(v))e[k]=String(v);else P(`Medição ${x.cod} em “${onde}”: campo “${k}” inválido (ignorado)`)}
    const lc=txt(x.local,LIM.curto),ob=txt(x.obs);if(lc===null||ob===null){P(`Medição ${x.cod} em “${onde}”: texto inválido (descartada)`);return}
    let sv=null;if(obj(x.sv)&&MODOS.includes(x.sv.m)&&["m","m²","m³","un"].includes(x.sv.u)&&(x.sv.u2===""||x.sv.u2==null||["m","m²","m³","un"].includes(x.sv.u2))){sv={m:x.sv.m,u:x.sv.u,u2:x.sv.u2||"",d:txt(x.sv.d,LIM.curto)||x.cod,r:txt(x.sv.r,LIM.curto)||"",g:txt(x.sv.g,LIM.curto)||""}}
    else{const r=svPara(x.cod,x.modo);sv=r.sv;
      if(x.sv!=null&&!svOk(x.sv))P(`Medição ${x.cod} em “${onde}”: unidade gravada inválida (usada a do catálogo)`);
      if(!sv)P(`Medição ${x.cod} em “${onde}”: item fora do catálogo deste aparelho – confira a unidade`);
      else if(r.mudouModo)P(`Medição ${x.cod} em “${onde}”: lançada como “${x.modo}”, mas o catálogo deste aparelho mede como “${sv.m}” (${sv.u}) – a quantidade será recalculada, confira`)}
    const o={id:x.id,estacaoId:x.estacaoId,ambienteId:x.ambienteId,servicoId:x.servicoId,cod:x.cod,modo:sv?sv.m:(MODOS.includes(x.modo)?x.modo:"area"),sv,e,local:lc,obs:ob,ordem:num(x.ordem)?x.ordem:n,criadoEm:num(x.criadoEm)?x.criadoEm:Date.now()};ids.add(x.id);med[x.id]=o;out.medicoes.push(o)});
  data.fotos.forEach((x,n)=>{
    if(!obj(x)||!idOk(x.id)||!amb[x.ambienteId]||amb[x.ambienteId].estacaoId!==x.estacaoId){P(`Foto nº ${n+1}: inválida ou de ambiente descartado`);return}
    const onde=amb[x.ambienteId].nome;
    if(!(Number.isInteger(x.w)&&x.w>0&&x.w<=10000&&Number.isInteger(x.h)&&x.h>0&&x.h<=10000)){P(`Foto em “${onde}”: dimensões inválidas (descartada)`);return}
    let item=x.itemId||null,itemOrig=null;if(item&&(!itm[item]||itm[item].ambienteId!==x.ambienteId)){P(`Foto em “${onde}”: anotação vinculada não veio válida no backup (fica em fotos gerais, salvo se a anotação continuar no aparelho)`);itemOrig=typeof item==="string"&&RX_ID.test(item)?item:null;item=null}
    let medicao=x.medicaoId||null,medOrig=null;if(medicao&&(!med[medicao]||med[medicao].ambienteId!==x.ambienteId)){P(`Foto em “${onde}”: medição vinculada não veio válida no backup (fica em fotos gerais, salvo se a medição continuar no aparelho)`);medOrig=typeof medicao==="string"&&RX_ID.test(medicao)?medicao:null;medicao=null}
    let leg=txt(x.legenda,LIM.curto);if(leg===null){P(`Foto em “${onde}”: legenda inválida (deixada em branco)`);leg=""}
    const dt=typeof x.data==="string"&&!isNaN(Date.parse(x.data))?x.data:new Date().toISOString();
    const geo=(v,l)=>num(v)&&Math.abs(v)<=l?v:null;
    const o={id:x.id,estacaoId:x.estacaoId,ambienteId:x.ambienteId,itemId:item,medicaoId:medicao,legenda:leg,data:dt,lat:geo(x.lat,90),lon:geo(x.lon,180),w:x.w,h:x.h,bytes:num(x.bytes)?x.bytes:null,ordem:num(x.ordem)?x.ordem:n};
    if(o.lat===null||o.lon===null){o.lat=null;o.lon=null}
    if(itemOrig)o._itemOrig=itemOrig;if(medOrig)o._medOrig=medOrig;
    ids.add(x.id);out.fotos.push(o)});
  for(const c of Array.isArray(data.config)?data.config:[]){
    if(obj(c)&&c.key==="modelo"&&obj(c.v)&&Array.isArray(c.v.etapas)){const v=c.v,M={};
      for(const k of ["unidade","equipe","responsaveis","objetivo","metodoIntro","metodoFim"]){const t=txt(v[k]);M[k]=t===null?(MODELO_PADRAO[k]||""):t}
      M.etapas=v.etapas.filter(e=>obj(e)&&txt(e.titulo,LIM.curto)).slice(0,50).map(e=>({titulo:e.titulo,descricao:txt(e.descricao)||"",ambientes:Array.isArray(e.ambientes)?e.ambientes.filter(a=>typeof a==="string"&&a.length<=LIM.curto).slice(0,300):[]}));
      out.config.push({key:"modelo",v:M})}
    if(obj(c)&&c.key==="catalogo"&&obj(c.v)&&Array.isArray(c.v.itens)){const it=c.v.itens.filter(s=>obj(s)&&typeof s.c==="string"&&RX_COD.test(s.c)&&MODOS.includes(s.m)&&["m","m²","m³","un"].includes(s.u)).slice(0,2000).map(s=>({c:s.c,d:(txt(s.d,LIM.curto)||s.c),u:s.u,u2:["m","m²","m³","un"].includes(s.u2)?s.u2:"",m:s.m,r:txt(s.r,LIM.curto)||"",t:Array.isArray(s.t)?s.t.filter(t=>TIPOS[t]):[],g:txt(s.g,LIM.curto)||"Outros",usar:s.usar!==false}));
      if(it.length)out.config.push({key:"catalogo",v:{itens:it,em:num(c.v.em)?c.v.em:Date.now(),arquivo:txt(c.v.arquivo,LIM.curto)||"backup"}})}}
  if(!out.estacoes.length)throw new Error("nenhuma estação válida no arquivo."+(prob.length?"\n"+prob.slice(0,5).join("\n"):""));
  return {data:out,problemas:prob};
}
/* Restauração.
   - Limites de tamanho DESCOMPACTADO (zip bomb), CRC e fim de JPEG conferidos em cada foto.
   - Ids que já pertencem a OUTRA estação do aparelho são recusados (não sobrescreve outra estação).
   - Para estação que já existe no aparelho: registros que o backup trouxe com defeito são MANTIDOS na versão do
     aparelho (mescla), e tudo o que seria apagado do aparelho é listado antes da confirmação, com a data do backup. */
async function restore(file){
  await flushSaves();
  let b=busy("Lendo backup…");
  try{
    if(file.size>2e9)throw new Error("arquivo grande demais");
    const zip=await JSZip.loadAsync(file);
    const tamDesc=f=>f&&f._data&&typeof f._data.uncompressedSize==="number"?f._data.uncompressedSize:null;
    let totalDesc=0;for(const k in zip.files){const t=tamDesc(zip.files[k]);if(t!==null){totalDesc+=t;if(t>60*1048576)throw new Error(`o arquivo interno “${k}” é grande demais (${(t/1048576).toFixed(0)} MB)`)}}
    if(totalDesc>3e9)throw new Error("conteúdo descompactado grande demais");
    const jf=zip.file("dados.json");if(!jf)throw new Error("dados.json não encontrado no arquivo");
    let raw;try{raw=JSON.parse(await jf.async("string"))}catch(e){throw new Error("dados.json corrompido")}
    b.set("Validando dados…");
    const {data,problemas}=validarBackup(raw);
    const geradoEm=raw&&typeof raw.geradoEm==="string"&&!isNaN(Date.parse(raw.geradoEm))?Date.parse(raw.geradoEm):null;
    const nomeAmb=id=>(data.ambientes.find(a=>a.id===id)||{}).nome||"?";
    // 1) ids que pertencem a outra estação no aparelho
    const estDe=o=>o.estacaoId;
    for(const k of SUB){
      const fica=[];for(const o of data[k]){const x=await dbGet(k,o.id);if(x&&x.estacaoId!==estDe(o))problemas.push(`Registro ${o.id} (${k}) já pertence a outra estação deste aparelho (recusado)`);else fica.push(o)}
      data[k]=fica}
    // 2) fotos: arquivo presente, tamanho, CRC e marcadores JPEG
    const blobs=[];let i=0,total=0;const fotosOk=[];
    for(const f of data.fotos){i++;if(i%10===0)b.set(`Validando fotos ${i}/${data.fotos.length}…`);
      const onde=nomeAmb(f.ambienteId);const zf=zip.file(`fotos/${f.id}.jpg`);
      if(!zf){problemas.push(`Foto em “${onde}”: arquivo ausente no backup`);continue}
      const u8=await zf.async("uint8array");
      const crcOk=!(zf._data&&typeof zf._data.crc32==="number")||crc32(u8)===(zf._data.crc32>>>0);
      const fimOk=u8.length>100&&u8.subarray(Math.max(0,u8.length-32)).some((v,k,a)=>v===0xFF&&a[k+1]===0xD9);
      if(u8.length<100||u8[0]!==0xFF||u8[1]!==0xD8||!crcOk||!fimOk){problemas.push(`Foto em “${onde}”: imagem corrompida`);continue}
      const zt=zip.file(`thumbs/${f.id}.jpg`);let t8=zt?await zt.async("uint8array"):u8;if(t8.length<100||t8[0]!==0xFF||t8[1]!==0xD8)t8=u8;
      total+=u8.length+t8.length;blobs.push({id:f.id,full:new Blob([u8],{type:"image/jpeg"}),thumb:new Blob([t8],{type:"image/jpeg"})});fotosOk.push(f)}
    data.fotos=fotosOk;
    // 3) poda em cascata depois das recusas (pais ausentes)
    const S=new Set(data.estacoes.map(x=>x.id));data.secoes=data.secoes.filter(x=>S.has(x.estacaoId));
    const SC=new Set(data.secoes.map(x=>x.id));data.ambientes=data.ambientes.filter(x=>SC.has(x.secaoId));
    const AM=new Set(data.ambientes.map(x=>x.id));data.itens=data.itens.filter(x=>AM.has(x.ambienteId));data.fotos=data.fotos.filter(x=>AM.has(x.ambienteId));data.servicos=data.servicos.filter(x=>AM.has(x.ambienteId));
    const SV=new Set(data.servicos.map(x=>x.id));data.medicoes=data.medicoes.filter(x=>SV.has(x.servicoId));
    const IT=new Set(data.itens.map(x=>x.id)),MD=new Set(data.medicoes.map(x=>x.id));data.fotos.forEach(f=>{if(f.itemId&&!IT.has(f.itemId)){f._itemOrig=f.itemId;f.itemId=null}if(f.medicaoId&&!MD.has(f.medicaoId)){f._medOrig=f.medicaoId;f.medicaoId=null}});
    const fotoIds=new Set(data.fotos.map(x=>x.id));const blobsOk=blobs.filter(x=>fotoIds.has(x.id));
    // 4) ids que vinham no arquivo mas ficaram de fora => versão do aparelho é mantida (mescla)
    const noBackup=new Set();for(const k of ["estacoes",...SUB])for(const x of raw[k]||[])if(x&&typeof x.id==="string")noBackup.add(x.id);
    const final=new Set();for(const k of SUB)data[k].forEach(x=>final.add(x.id));
    const manter=new Set(),perdas=[],resumo=[];
    for(const e of data.estacoes){
      const dev=await dbGet("estacoes",e.id);if(!dev)continue;
      const D={};for(const k of SUB)D[k]=await dbBy(k,"estacaoId",e.id);
      // manter do aparelho o que o backup trouxe com defeito, respeitando a cadeia de pais
      const ok=id=>final.has(id)||manter.has(id);
      for(const k of SUB)for(const x of D[k]){
        if(final.has(x.id)||!noBackup.has(x.id))continue;
        const pai=k==="secoes"?true:k==="ambientes"?ok(x.secaoId):k==="medicoes"?ok(x.ambienteId)&&ok(x.servicoId):ok(x.ambienteId);if(pai)manter.add(x.id)}
      const perde=k=>D[k].filter(x=>!final.has(x.id)&&!manter.has(x.id));
      const pa=perde("ambientes"),pi=perde("itens"),pf=perde("fotos"),ps=perde("secoes"),pm=perde("medicoes"),pv=perde("servicos");
      const porAmb={};const nomeDev=id=>(D.ambientes.find(a=>a.id===id)||{}).nome||nomeAmb(id);
      const pA=id=>porAmb[id]=porAmb[id]||{i:0,f:0,m:0};pi.forEach(x=>pA(x.ambienteId).i++);pf.forEach(x=>pA(x.ambienteId).f++);pm.forEach(x=>pA(x.ambienteId).m++);
      const alt=ALT[e.id]||await cfg("alteradoEst_"+e.id,0);
      resumo.push({id:e.id,nome:dev.nome,maisNovo:geradoEm&&alt>geradoEm,manteve:[...manter].filter(id=>SUB.some(k=>D[k].some(x=>x.id===id))).length,
        perdas:[...ps.map(x=>`Etapa “${x.titulo}”`),...pa.map(x=>`Ambiente “${x.nome}”`),...Object.entries(porAmb).map(([id,c])=>`${nomeDev(id)}: ${[c.m?c.m+" medição(ões)":"",c.i?c.i+" anotação(ões)":"",c.f?c.f+" foto(s)":""].filter(Boolean).join(", ")}`)]});
      perdas.push(...pa,...pi,...pf,...ps,...pm,...pv)}
    // vínculos de foto: se o aparelho mantém a anotação/medição original, a foto volta a apontar para ela
    for(const f of data.fotos){if(f._medOrig&&manter.has(f._medOrig)){const dv=await dbGet("medicoes",f._medOrig);if(dv&&dv.ambienteId===f.ambienteId)f.medicaoId=f._medOrig}
      if(f._itemOrig&&manter.has(f._itemOrig)){const dv=await dbGet("itens",f._itemOrig);if(dv&&dv.ambienteId===f.ambienteId)f.itemId=f._itemOrig}
      delete f._medOrig;delete f._itemOrig}
    const livre=await espacoLivreMB();if(livre<total/1048576*1.3+20)throw new Error(`espaço insuficiente (precisa de ~${(total/1048576*1.3+20).toFixed(0)} MB, há ~${livre.toFixed(0)} MB)`);
    b.close();
    // 5) confirmação única, com tudo à vista
    const trocaModelo=data.config.some(c=>c.key==="modelo"||c.key==="catalogo");
    const dataTxt=geradoEm?new Date(geradoEm).toLocaleString("pt-BR"):"desconhecida";
    const html=`<h3>Restaurar backup</h3>
      <div class="mu">Backup gerado em <b>${esc(dataTxt)}</b> · ${data.estacoes.length} estação(ões), ${data.medicoes.length} medições, ${data.itens.length} anotações, ${data.fotos.length} fotos.</div>
      ${problemas.length?`<div class="warn" style="margin-top:10px"><b>${problemas.length} problema(s) no arquivo</b> – esses registros não serão importados${resumo.some(r=>r.manteve)?"; quando existirem neste aparelho, a versão do aparelho é mantida":""}:<div style="max-height:22vh;overflow:auto;margin-top:6px;font-size:13px">${problemas.map(p=>"• "+esc(p)).join("<br>")}</div></div>`:""}
      ${resumo.map(r=>`<div class="card" style="margin-top:10px"><b>${esc(r.nome)}</b> já existe neste aparelho e será substituída pela versão do backup.
        ${r.maisNovo?`<div class="warn" style="margin:8px 0 0">⚠ A estação foi alterada neste aparelho DEPOIS da data deste backup. Restaurar desfaz essas alterações.</div>`:""}
        ${r.manteve?`<div class="mu" style="margin-top:6px">${r.manteve} registro(s) com defeito no backup serão mantidos como estão no aparelho.</div>`:""}
        ${r.perdas.length?`<div style="margin-top:6px"><b style="color:var(--red)">Serão APAGADOS do aparelho</b> (não existem no backup):<div style="max-height:20vh;overflow:auto;font-size:13px;margin-top:4px">${r.perdas.map(p=>"• "+esc(p)).join("<br>")}</div></div>`:`<div class="mu" style="margin-top:6px">Nada do aparelho será apagado.</div>`}</div>`).join("")}
      ${trocaModelo?`<div class="mu" style="margin-top:10px">A lista-modelo de ambientes, os textos padrão e o catálogo de serviços (se vier no arquivo) também serão substituídos. As opções de privacidade deste aparelho não mudam.</div>`:""}
      <div class="mu" style="margin-top:10px">Cancelar não altera nada. Se a gravação falhar no meio, os dados atuais são mantidos.</div>
      <div class="row" style="margin-top:12px"><button class="btn grow" id="rpNo">Cancelar</button><button class="btn p grow" id="rpOk">${perdas.length?"Restaurar e apagar o listado":"Restaurar"}</button></div>`;
    const ok=await new Promise(res=>{const m=sheet(html);let r=false;m.addEventListener("remove-modal",()=>res(r));m.querySelector("#rpNo").onclick=()=>m.remove();m.querySelector("#rpOk").onclick=()=>{r=true;m.remove()}});
    if(!ok)return;
    b=busy("Restaurando…");
    const ficaPorEst={};for(const e of data.estacoes)ficaPorEst[e.id]=true;
    await enqueue(()=>txRun([...ALL,"config"],t=>{
      let n=data.estacoes.length*SUB.length;const gravar=()=>{
        for(const k of ["estacoes",...SUB,"config"])for(const o of data[k])t.objectStore(k).put(o);
        for(const o of blobsOk)t.objectStore("blobs").put(o)};
      // apaga do aparelho só o que não está no resultado final nem na lista de mantidos
      for(const e of data.estacoes)for(const sn of SUB){
        const r=t.objectStore(sn).index("estacaoId").getAllKeys(e.id);
        r.onsuccess=()=>{for(const k of r.result)if(!final.has(k)&&!manter.has(k)){t.objectStore(sn).delete(k);if(sn==="fotos")t.objectStore("blobs").delete(k)}if(--n===0)gravar()}}
    }));
    for(const e of data.estacoes){const mesclou=resumo.some(r=>r.id===e.id&&r.manteve);await enqueue(()=>setCfg("alteradoEst_"+e.id,mesclou||!geradoEm?Date.now():geradoEm));ALT[e.id]=mesclou||!geradoEm?Date.now():geradoEm}
    await carregarCatalogo();b.close();toast(problemas.length?"Backup restaurado (parte válida)":"Backup restaurado");location.hash="#/";render();
  }catch(err){b.close();document.querySelectorAll(".busy").forEach(x=>x.remove());const msg=/quota/i.test(String(err&&(err.name+err.message)))?"falta de espaço no aparelho":err&&err.name==="AbortError"?"a gravação foi interrompida (geralmente falta de espaço)":(err&&err.message||err);
    alert("Restauração cancelada — nenhum dado do aparelho foi alterado.\n\nMotivo: "+msg)}
}

async function armazenamentoPersistente(pedir){
  if(!navigator.storage||!navigator.storage.persisted)return false;
  try{let p=await navigator.storage.persisted();if(!p&&pedir&&navigator.storage.persist)p=await navigator.storage.persist();return p}catch(e){return false}}
/* aviso antes de exportações grandes (tudo é montado na memória do celular) */
async function avisoVolume(D,oque){
  let bytes=0;for(const f of D.fotos)bytes+=f.bytes||350000;const mb=bytes/1048576;
  if(mb>150&&!confirm(`${oque}: cerca de ${mb.toFixed(0)} MB de fotos serão montados na memória do celular. Em aparelhos com pouca RAM o app pode fechar no meio.

Recomendado: faça o backup antes e, se falhar, gere pelo computador (restaurando o backup no Chrome do PC).

Continuar?`))return false;
  return true}

/* ====================== QUANTITATIVOS ====================== */
const TIPOS={PLA:"Plataforma",COB:"Coberta/laje",ACE:"Acessos (rampas, escadas, passarela)",SAG:"Saguão/bilheteria",FAC:"Fachada",SAN:"Sanitário",TEC:"Sala técnica/operacional",ADM:"Sala administrativa",EXT:"Área externa/entorno",GER:"Itens gerais da estação"};
const TIPO_CURTO={PLA:"Plataforma",COB:"Coberta",ACE:"Acessos",SAG:"Saguão",FAC:"Fachada",SAN:"Sanitário",TEC:"Sala técnica",ADM:"Sala adm.",EXT:"Área externa",GER:"Estação (geral)"};
const TIPO_DE_NOME={};for(const [k,v] of Object.entries(TIPOS)){TIPO_DE_NOME[v.toLowerCase()]=k;TIPO_DE_NOME[TIPO_CURTO[k].toLowerCase()]=k;TIPO_DE_NOME[k.toLowerCase()]=k}
function inferTipo(nome){const n=String(nome||"").normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase();
  if(/itens gerais|geral da estacao/.test(n))return"GER";
  if(/coberta|telhad|laje|cobertura/.test(n))return"COB";
  if(/plataforma/.test(n))return"PLA";
  if(/fachada/.test(n))return"FAC";
  if(/banheir|sanitari|wc/.test(n))return"SAN";
  if(/saguao|mezanino|bilheteria/.test(n))return"SAG";
  if(/acesso|rampa|escada|passarela|guarda-corpo/.test(n))return"ACE";
  if(/calcada|entorno|estacionamento|externa|drenagem|muro/.test(n))return"EXT";
  if(/rele|telecom|ggd|sco|comando|subesta|sse|tecnic|gerador|bomba|quadro/.test(n))return"TEC";
  return"ADM"}
/* "Nome | Tipo" (lista-modelo) → {nome,tipo} */
function parseAmbModelo(s){const [n,t]=String(s).split("|").map(x=>(x||"").trim());const tk=t&&TIPO_DE_NOME[t.toLowerCase()];return{nome:n.slice(0,UI_MAX.curto),tipo:tk||inferTipo(n)}}
const ESTADOS={exec:"Executar",ok:"Ok",na:"N/A"};
const MODOS=["area","comprimento","contagem","volume","vao_luz","vao_luz_2x","pintura_metal","projecao","por_estacao"];

/* ---------- catálogo em uso (padrão ou importado da planilha) ---------- */
let CAT=[],CATM={};
function setCatalogo(lista){CAT=lista;CATM={};CAT.forEach((s,i)=>{s.i=i;CATM[s.c]=s})}
async function carregarCatalogo(){const c=await cfg("catalogo",null);setCatalogo(c&&Array.isArray(c.itens)&&c.itens.length?c.itens:CATALOGO_PADRAO.map(x=>({...x,usar:true})))}
const capitulo=cod=>String(cod).split(".")[0];
const cmpCod=(a,b)=>{const x=String(a).split(".").map(Number),y=String(b).split(".").map(Number);for(let i=0;i<Math.max(x.length,y.length);i++){const d=(x[i]||0)-(y[i]||0);if(d)return d}return 0};
const svcInfo=cod=>CATM[cod]||{c:cod,d:"(serviço fora do catálogo atual)",u:"",u2:"",m:"area",r:"",t:[],g:"Outros"};
/* a medição guarda a unidade, o modo e a descrição do catálogo do momento em que foi lançada (sv):
   trocar o catálogo depois não recalcula nem muda a unidade de medições antigas */
const SV_CAMPOS=["m","u","u2","d","r","g"];
const svSnap=s=>{const o={};for(const k of SV_CAMPOS)o[k]=s[k]??"";return o};
const UNIDS=["m","m²","m³","un"];
const svOk=sv=>!!(sv&&MODOS.includes(sv.m)&&UNIDS.includes(sv.u)&&(!sv.u2||UNIDS.includes(sv.u2)));
const medSvc=m=>m&&svOk(m.sv)?{...svcInfo(m.cod),...m.sv,c:m.cod}:svcInfo(m.cod);
let PADRAO_M=null;const padrao=cod=>{if(!PADRAO_M){PADRAO_M={};CATALOGO_PADRAO.forEach(x=>PADRAO_M[x.c]=x)}return PADRAO_M[cod]||null};
/* item do catálogo para gravar na medição: o atual; senão o padrão; com modo conhecido (backup antigo), prefere o que tem o mesmo modo */
function svPara(cod,modo){const cands=[CATM[cod],padrao(cod)].filter(Boolean);
  const c=(MODOS.includes(modo)&&cands.find(x=>x.m===modo))||cands[0]||null;return c?{sv:svSnap(c),mudouModo:!!(MODOS.includes(modo)&&c.m!==modo)}:{sv:null,mudouModo:false}}

/* ---------- números ---------- */
function pnum(s){if(typeof s==="number")return s;s=String(s??"").trim().replace(/\s/g,"");if(!s)return NaN;if(s.includes(","))s=s.replace(/\./g,"").replace(",",".");return /^-?\d*\.?\d+$/.test(s)?parseFloat(s):NaN}
const r2=v=>Math.round((v+Number.EPSILON)*100)/100;
const fmt=(v,d=2)=>isFinite(v)?Number(v).toLocaleString("pt-BR",{minimumFractionDigits:d,maximumFractionDigits:d}):"–";
const fmtN=v=>isFinite(v)?(Number.isInteger(v)?String(v):fmt(v)):"–";
const fq=(v,u)=>u==="un"&&Number.isInteger(v)?String(v):fmt(v);

/* ---------- geometria ---------- */
const GEO_NOME={piso:"área de piso",perim:"perímetro",pd:"pé-direito",vaos:"vãos"};
function geoDerivada(amb){const g=amb.geo||{};
  for(const k of ["piso","perim","pd","vaos"]){const er=checarValor(g[k]);if(er)return{piso:NaN,teto:NaN,parede:NaN,perim:NaN,erro:"Geometria ("+GEO_NOME[k]+"): "+er}}
  const piso=pnum(g.piso),per=pnum(g.perim),pd=pnum(g.pd),vaos=pnum(g.vaos);
  const bruta=isFinite(per)&&isFinite(pd)?per*pd:NaN;
  if(isFinite(bruta)&&isFinite(vaos)&&vaos>bruta)return{piso:isFinite(piso)?piso:NaN,teto:isFinite(piso)?piso:NaN,parede:NaN,perim:per,erro:"Geometria: vãos maiores que a área das paredes"};
  return{piso:isFinite(piso)?piso:NaN,teto:isFinite(piso)?piso:NaN,parede:isFinite(bruta)?r2(bruta-(isFinite(vaos)?vaos:0)):NaN,perim:isFinite(per)?per:NaN}}
const BASES={piso:"piso",parede:"paredes",teto:"teto"};

/* ---------- cálculo de uma medição (sempre a partir das entradas; a geometria pode mudar depois) ---------- */
function opcoesModo(s){
  switch(s.m){case "area":return[["dim","Medidas (C × L)"],["pct","% da geometria"],["dir","Valor direto"]];
    case "pintura_metal":return[["vazada","Vazada: vão luz (L × A)"],["cubo","Irregular: cubo envolvente"],["tubo","Tubo: π·Ø × comprimento"],["dir","Valor direto"]];
    case "contagem":return[["cnt","Contagem"]];case "por_estacao":return[["dir","Quantidade"]];
    default:return[["dim","Medidas"],["dir","Valor direto"]]}}
const NUM_CAMPOS=["c","l","n","desc","pct","v","h","a","d","v2","esp","c2","l2","n2","h2"];
const INT_CAMPOS=["n","n2"];
/* campos que valem para a forma de medir atual (os outros são ignorados e não são gravados) */
function camposAtivos(s,e){const sub=e.sub||opcoesModo(s)[0][0];let k;
  if(sub==="dir")k=["v"];else if(sub==="cnt")k=["n"];
  else switch(s.m){case "area":k=sub==="pct"?["base","pct"]:["c","l","n","desc"];break;
    case "projecao":k=["c","l","n"];break;case "comprimento":k=["c","n"];break;case "volume":k=["c","l","h","n"];break;
    case "vao_luz":case "vao_luz_2x":k=["l","a","n","fat"];break;
    case "pintura_metal":k=sub==="tubo"?["d","c","n"]:sub==="cubo"?["c","l","h","n"]:["l","a","n"];break;default:k=[]}
  if(s.u2){k.push("v2");if(s.u==="m²"&&s.u2==="m³")k.push("esp");else if(s.u2==="m")k.push("c2","n2");else if(s.u2==="m²")k.push("c2","l2","n2");else if(s.u2==="m³")k.push("c2","l2","h2")}
  return ["sub",...k]}
function checarValor(raw){if(raw==null||String(raw).trim()==="")return null;const t=String(raw).trim().replace(/\s/g,"");
  if(/^-?\d{1,3}(\.\d{3})+$/.test(t))return `“${t}”: use vírgula para decimal e não use ponto de milhar (ex.: 1250 ou 1,25)`;
  const v=pnum(t);if(!isFinite(v))return `“${t}” não é um número`;if(v<0)return "Valores negativos não são aceitos";return null}
function checarEntradas(e,sub,ativos){
  for(const k of NUM_CAMPOS){if(ativos&&!ativos.includes(k))continue;const raw=e[k];if(raw==null||String(raw).trim()==="")continue;const t=String(raw).trim().replace(/\s/g,"");
    if(/^-?\d{1,3}(\.\d{3})+$/.test(t))return `“${t}”: use vírgula para decimal e não use ponto de milhar (ex.: 1250 ou 1,25)`;
    const v=pnum(t);if(!isFinite(v))return `“${t}” não é um número`;
    if(v<0)return "Valores negativos não são aceitos";
    if(k==="n"&&sub==="cnt"){if(!Number.isInteger(v))return "A contagem deve ser um número inteiro";continue}
    if(INT_CAMPOS.includes(k)&&!Number.isInteger(v))return "O nº de vezes/trechos deve ser um número inteiro";
    if(INT_CAMPOS.includes(k)&&v<1)return "O nº de vezes/trechos deve ser 1 ou mais";
    if(k==="pct"&&v>100)return "A porcentagem deve estar entre 0 e 100"}
  return null}
function calcMed(m,amb){
  const s=medSvc(m),e=m.e||{},sub=e.sub||opcoesModo(s)[0][0],u=s.u;
  const invalida=checarEntradas(e,sub,camposAtivos(s,e));if(invalida)return{q1:NaN,f1:"",erro:invalida,q2:NaN,f2:""};
  const v=k=>pnum(e[k]),n=k=>{const x=pnum(e[k]);return isFinite(x)?x:1};
  const ok=(q,f)=>isFinite(q)&&q>=0?{q:r2(q),f:f+" = "+fq(r2(q),u)+" "+u}:{q:NaN,f:"",erro:"Preencha as medidas"};
  let R;
  if(sub==="dir"){const q=v("v");R=isFinite(q)?{q:r2(q),f:"Valor informado: "+fq(r2(q),u)+" "+u}:{q:NaN,f:"",erro:"Informe a quantidade"}}
  else if(sub==="cnt"){const q=v("n");R=isFinite(q)?{q,f:"Contagem: "+fmtN(q)+" "+u}:{q:NaN,f:"",erro:"Informe a quantidade"}}
  else switch(s.m){
    case "area":
      if(sub==="pct"){const G=geoDerivada(amb),b=e.base||"piso",base=G[b],p=v("pct");
        R=G.erro?{q:NaN,f:"",erro:G.erro}:!isFinite(base)?{q:NaN,f:"",erro:"Preencha a geometria do ambiente ("+BASES[b]+")"}:ok(base*p/100,fmt(p,0)+"% × "+BASES[b]+" "+fmt(base)+" m²")}
      else{const c=v("c"),l=v("l"),d=v("desc");if(isFinite(c)&&isFinite(l)&&isFinite(d)&&d>c*l*n("n")){R={q:NaN,f:"",erro:"Desconto maior que a área"};break}R=ok(c*l*n("n")-(isFinite(d)?d:0),fmt(c)+" × "+fmt(l)+(n("n")!==1?" × "+fmtN(n("n")):"")+(isFinite(d)&&d?" − "+fmt(d):""))}break;
    case "projecao":{const c=v("c"),l=v("l");R=ok(c*l*n("n"),"Projeção "+fmt(c)+" × "+fmt(l)+(n("n")!==1?" × "+fmtN(n("n")):""));break}
    case "comprimento":{const c=v("c");R=ok(c*n("n"),fmt(c)+(n("n")!==1?" × "+fmtN(n("n")):""));break}
    case "volume":{const c=v("c"),l=v("l"),h=v("h");R=ok(c*l*h*n("n"),fmt(c)+" × "+fmt(l)+" × "+fmt(h)+(n("n")!==1?" × "+fmtN(n("n")):""));break}
    case "vao_luz":case "vao_luz_2x":{const fat=s.m==="vao_luz_2x"?2:(pnum(e.fat)===2?2:1),l=v("l"),a=v("a");
      R=ok(l*a*n("n")*fat,fmt(l)+" × "+fmt(a)+(n("n")!==1?" × "+fmtN(n("n")):"")+" × "+fat+" ("+fat+"× vão luz"+(s.c==="12.2.1"?(fat===2?", veneziana":", com vidro"):"")+")");break}
    case "pintura_metal":
      if(sub==="tubo"){const d=v("d"),c=v("c");R=ok(Math.PI*d*c*n("n"),"π × Ø "+fmt(d,3)+" × "+fmt(c)+(n("n")!==1?" × "+fmtN(n("n")):""))}
      else if(sub==="cubo"){const c=v("c"),l=v("l"),h=v("h");R=ok(2*(c*l+c*h+l*h)*n("n"),"Cubo envolvente 2 × ("+fmt(c)+"×"+fmt(l)+" + "+fmt(c)+"×"+fmt(h)+" + "+fmt(l)+"×"+fmt(h)+")"+(n("n")!==1?" × "+fmtN(n("n")):""))}
      else{const l=v("l"),a=v("a");R=ok(l*a*n("n"),"Vão luz "+fmt(l)+" × "+fmt(a)+(n("n")!==1?" × "+fmtN(n("n")):""))}break;
    default:R={q:NaN,f:"",erro:"Modo desconhecido"}}
  // 2ª unidade
  let R2=null;
  if(s.u2){const u2=s.u2,x=k=>pnum(e[k]);
    const ok2=(q,f)=>isFinite(q)&&q>=0?{q:r2(q),f:f+" = "+fq(r2(q),u2)+" "+u2}:{q:NaN,f:""};
    if(isFinite(x("v2")))R2={q:r2(x("v2")),f:"Valor informado: "+fq(r2(x("v2")),u2)+" "+u2};
    else if(u==="m²"&&u2==="m³"&&isFinite(x("esp"))&&isFinite(R.q))R2=ok2((R.q||0)*x("esp"),fmt(R.q)+" m² × espessura "+fmt(x("esp"),3)+" m");
    else if(u2==="m")R2=ok2(x("c2")*(isFinite(x("n2"))?x("n2"):1),fmt(x("c2"))+(isFinite(x("n2"))&&x("n2")!==1?" × "+fmtN(x("n2")):""));
    else if(u2==="m²")R2=ok2(x("c2")*x("l2")*(isFinite(x("n2"))?x("n2"):1),fmt(x("c2"))+" × "+fmt(x("l2"))+(isFinite(x("n2"))&&x("n2")!==1?" × "+fmtN(x("n2")):""));
    else if(u2==="m³")R2=ok2(x("c2")*x("l2")*x("h2"),fmt(x("c2"))+" × "+fmt(x("l2"))+" × "+fmt(x("h2")));
    if(R2&&!isFinite(R2.q))R2=null}
  return{q1:R.q,f1:R.f,erro:R.erro,q2:R2?R2.q:NaN,f2:R2?R2.f:""};
}
/* chaves de entrada aceitas (backup e formulário) */
const MED_CAMPOS=["sub","c","l","n","desc","base","pct","v","h","a","fat","d","v2","esp","c2","l2","n2","h2"];

/* ---------- dados ---------- */
function svcDoAmb(D,ambId){const amb=D.ambientes.find(a=>a.id===ambId);const reg=D.servicos.filter(s=>s.ambienteId===ambId);
  const cods=new Set(CAT.filter(s=>s.usar!==false&&amb&&s.t.includes(amb.tipo)).map(s=>s.c));reg.forEach(r=>cods.add(r.cod));
  return [...cods].sort(cmpCod).map(c=>({cod:c,s:svcInfo(c),reg:reg.find(r=>r.cod===c)||null,meds:D.medicoes.filter(m=>m.ambienteId===ambId&&m.cod===c).sort((a,b)=>a.ordem-b.ordem)}))}
/* totais por item E unidade (chave "cod|u|u2"): medições de unidades diferentes nunca se somam */
const chaveCod=k=>k.split("|")[0];
const cmpChave=(a,b)=>cmpCod(chaveCod(a),chaveCod(b))||a.localeCompare(b);
function totaisEst(D){/* {"cod|u|u2":{cod,q1,q2,u,u2,ambs:Set,n}} só de serviços marcados Executar */
  const T={};const execAmb=new Set(D.servicos.filter(s=>s.estado==="exec").map(s=>s.ambienteId+"|"+s.cod));
  for(const m of D.medicoes){if(!execAmb.has(m.ambienteId+"|"+m.cod))continue;const amb=D.ambientes.find(a=>a.id===m.ambienteId);if(!amb)continue;
    const r=calcMed(m,amb),sv=medSvc(m);const key=m.cod+"|"+sv.u+"|"+(sv.u2||"");const t=T[key]=T[key]||{cod:m.cod,q1:0,q2:0,ambs:new Set(),n:0,erros:0,u:sv.u,u2:sv.u2||"",d:sv.d,g:sv.g};
    if(isFinite(r.q1))t.q1=r2(t.q1+r.q1);else t.erros++;if(isFinite(r.q2))t.q2=r2(t.q2+r.q2);t.ambs.add(amb.id);t.n++}
  return T}
function pendencias(D){const P={semVerif:0,execSemMed:[],medForaExec:[],unidMistas:[],medSemFoto:0,ambs:{}};
  {const vistos={};for(const t of Object.values(totaisEst(D)))vistos[t.cod]=(vistos[t.cod]||0)+1;for(const [c,n] of Object.entries(vistos))if(n>1)P.unidMistas.push(c)}
  for(const a of D.ambientes){const L=svcDoAmb(D,a.id);const nv=L.filter(x=>!x.reg||!x.reg.estado).length;P.semVerif+=nv;P.ambs[a.id]={nv,total:L.length,exec:L.filter(x=>x.reg&&x.reg.estado==="exec").length};
    L.filter(x=>x.reg&&x.reg.estado==="exec"&&!x.meds.length).forEach(x=>P.execSemMed.push(a.nome+" › "+x.cod));
    L.filter(x=>x.meds.length&&!(x.reg&&x.reg.estado==="exec")).forEach(x=>P.medForaExec.push(a.nome+" › "+x.cod+" ("+x.meds.length+")"))}
  P.medSemFoto=D.medicoes.filter(m=>!D.fotos.some(f=>f.medicaoId===m.id)).length;return P}

async function setEstado(ambId,cod,estado){
  const amb=ctx.D.ambientes.find(a=>a.id===ambId);
  await enqueue(()=>txRun(["servicos"],t=>{const os=t.objectStore("servicos");const r=os.index("ambienteId").getAll(ambId);
    r.onsuccess=()=>{const ex=r.result.find(x=>x.cod===cod);
      if(ex){ex.estado=ex.estado===estado?"":estado;os.put(ex)}
      else os.put({id:uid(),estacaoId:amb.estacaoId,ambienteId:ambId,cod,estado,extra:!(svcInfo(cod).t||[]).includes(amb.tipo),ordem:ordNow()})}}));
  alterou(amb.estacaoId)}

/* ---------- tela do ambiente: quantitativos ---------- */
async function viewQuantAmb(amb,D,N,lista,idx){
  const prev=lista[idx-1],next=lista[idx+1];const L=svcDoAmb(D,amb.id);const G=geoDerivada(amb);
  const filtro=ctx.filtroSvc||"todos";
  const nv=L.filter(x=>!x.reg||!x.reg.estado).length,ne=L.filter(x=>x.reg&&x.reg.estado==="exec").length;
  const thumbs=async m=>{const fs=D.fotos.filter(f=>f.medicaoId===m.id);return (await Promise.all(fs.map(async f=>`<span class="fig"><img data-a="foto" data-id="${esc(f.id)}" src="${await thumbURL(f.id)}" alt="Figura ${N.foto[f.id]||""}" role="button" tabindex="0"><b>${N.foto[f.id]||""}</b></span>`))).join("")};
  let grupos="",gAtual=null;
  for(const x of L){
    const est=x.reg?x.reg.estado:"";
    if(filtro==="pend"&&est)continue;if(filtro==="exec"&&est!=="exec")continue;
    if(x.s.g!==gAtual){if(gAtual!==null)grupos+="</div>";gAtual=x.s.g;grupos+=`<h2>${esc(gAtual)}</h2><div>`}
    let meds="";
    const su=x.meds.length?medSvc(x.meds[0]):x.s;
    if(est!=="exec"&&x.meds.length)meds=`<div class="warn" style="margin:10px 0 0">⚠ ${x.meds.length} medição(ões) guardada(s) <b>fora da conta</b>. Marque <b>Executar</b> para incluir na planilha.</div>`;
    if(est==="exec"){let err=0;const tot={};
      for(const m of x.meds){const r=calcMed(m,amb),sm=medSvc(m);const tk=sm.u+"|"+(sm.u2||"");const tt=tot[tk]=tot[tk]||{u:sm.u,u2:sm.u2||"",q1:0,q2:0};if(isFinite(r.q1))tt.q1+=r.q1;else err++;if(isFinite(r.q2))tt.q2+=r.q2;
        meds+=`<div class="med" data-a="medEdit" data-id="${esc(m.id)}" role="button" tabindex="0"><div class="grow"><div><b>${esc(m.local||"Medição")}</b></div><div class="mu">${esc(r.f1||r.erro||"")}${r.f2?"<br>"+esc(r.f2):""}</div><div class="thumbs">${await thumbs(m)}</div></div><button class="btn sm" data-a="medFoto" data-id="${esc(m.id)}" aria-label="Foto desta medição">📷</button></div>`}
      meds=`<div class="meds">${meds||'<div class="mu" style="padding:6px 0">Nenhuma medição ainda.</div>'}
        <div class="row" style="margin-top:6px"><b class="grow">Total: ${(Object.values(tot).map(tt=>`${fq(r2(tt.q1),tt.u)} ${esc(tt.u)}${tt.u2?` · ${fq(r2(tt.q2),tt.u2)} ${esc(tt.u2)}`:""}`).join(" + ")||"0,00 "+esc(su.u))}${err?` <span style="color:var(--red)">(${err} incompleta)</span>`:""}</b>
        <button class="btn sm p" data-a="medNova" data-cod="${esc(x.cod)}">＋ Medição</button></div></div>`}
    grupos+=`<div class="card svc st-${est||"nao"}" id="svc-${esc(x.cod.replace(/\./g,"_"))}"><div class="row" style="align-items:flex-start"><span class="num">${esc(x.cod)}</span><div class="grow"><div class="desc">${esc(x.s.d)}</div><div class="mu">${esc(x.s.u)}${x.s.u2?" + "+esc(x.s.u2):""} · ${esc(x.s.r)}${x.meds.some(m=>medSvc(m).u!==x.s.u)?` · <b style="color:var(--red)">há medições antigas em ${esc([...new Set(x.meds.map(m=>medSvc(m).u).filter(u=>u!==x.s.u))].join(", "))}</b>`:""}${x.reg&&x.reg.extra?" · <i>incluído neste ambiente</i>":""}</div></div></div>
      <div class="sts" role="group" aria-label="Situação do item ${esc(x.cod)}">${Object.entries(ESTADOS).map(([k,l])=>`<button class="stb ${est===k?"on "+k:""}" data-a="svcEst" data-cod="${esc(x.cod)}" data-k="${k}" aria-pressed="${est===k}">${l}</button>`).join("")}</div>${meds}</div>`}
  if(gAtual!==null)grupos+="</div>";
  const nNotas=D.itens.filter(i=>i.ambienteId===amb.id).length+D.fotos.filter(f=>f.ambienteId===amb.id&&!f.medicaoId).length;
  app.innerHTML=topbar(amb.nome,TIPO_CURTO[amb.tipo]+" · "+(idx+1)+"/"+lista.length,"#/e/"+amb.estacaoId+"/campo",`<button class="ib" aria-label="Ambiente anterior" ${prev?`data-a="go" data-h="#/a/${esc(prev.id)}"`:"disabled style='opacity:.3'"}>‹</button><button class="ib" aria-label="Próximo ambiente" ${next?`data-a="go" data-h="#/a/${esc(next.id)}"`:"disabled style='opacity:.3'"}>›</button>`)+
  `<main><nav class="tabs"><a href="#/a/${esc(amb.id)}" class="on">Quantitativos</a><a href="#/a/${esc(amb.id)}/notas">Anotações e fotos${nNotas?` (${nNotas})`:""}</a></nav>
  ${amb.tipo==="GER"?"":`<details class="card" ${amb.geo&&(amb.geo.piso||amb.geo.perim)?"":"open"}><summary><b>Geometria do ambiente</b> <span class="mu">${isFinite(G.piso)?"piso "+fmt(G.piso)+" m²":"não informada"}${isFinite(G.parede)?" · paredes "+fmt(G.parede)+" m²":""}</span></summary>
    <div class="mu" style="margin:6px 0">Opcional. Permite lançar serviços como “% do piso / das paredes / do teto”.</div>
    <div class="g2"><label>Área de piso (m²)<input type="text" inputmode="decimal" data-a="geo" data-k="piso" value="${esc(amb.geo&&amb.geo.piso||"")}"></label>
    <label>Perímetro (m)<input type="text" inputmode="decimal" data-a="geo" data-k="perim" value="${esc(amb.geo&&amb.geo.perim||"")}"></label>
    <label>Pé-direito (m)<input type="text" inputmode="decimal" data-a="geo" data-k="pd" value="${esc(amb.geo&&amb.geo.pd||"")}"></label>
    <label>Vãos a descontar (m²)<input type="text" inputmode="decimal" data-a="geo" data-k="vaos" value="${esc(amb.geo&&amb.geo.vaos||"")}"></label></div>
    <div class="mu" id="geoDer" style="margin-top:6px">${geoTxt(G)}</div></details>`}
  <div class="card"><div class="row"><b class="grow">${L.length-nv}/${L.length} serviços verificados</b><span class="mu">${ne} a executar</span></div><div class="prog"><i style="width:${L.length?(L.length-nv)/L.length*100:0}%"></i></div>
    <div class="row" style="margin-top:8px;gap:6px">${[["todos","Todos"],["pend","Não verificados"],["exec","Executar"]].map(([k,l])=>`<button class="chip ${filtro===k?"fon":""}" data-a="filtroSvc" data-k="${k}">${l}</button>`).join("")}</div><div class="row" style="margin-top:8px"><label class="mu grow" style="margin:0;display:flex;align-items:center;gap:8px">Tipo do ambiente <select data-a="ambTipo" class="grow" style="padding:6px">${Object.entries(TIPO_CURTO).map(([k,v])=>`<option value="${k}" ${amb.tipo===k?"selected":""}>${v}</option>`).join("")}</select></label></div></div>
  ${grupos||`<div class="empty">${filtro==="todos"?"Nenhum serviço do catálogo para este tipo de ambiente.":"Nada neste filtro."}</div>`}
  </main>
  <div class="bar"><button class="btn" data-a="svcAdd">＋ Serviço do caderno<small>buscar por item ou palavra</small></button>${nv?`<button class="btn" data-a="okRestantes">✓ Demais Ok<small>${nv} não verificados</small></button>`:""}</div>`;
  if(ctx.scrollSvc){const el=document.getElementById("svc-"+ctx.scrollSvc.replace(/\./g,"_"));ctx.scrollSvc=null;if(el)el.scrollIntoView({block:"center"})}
}
const geoTxt=G=>G.erro?`⚠ ${G.erro}`:`Derivadas: piso/teto ${isFinite(G.piso)?fmt(G.piso)+" m²":"–"} · paredes ${isFinite(G.parede)?fmt(G.parede)+" m² (perímetro × pé-direito − vãos)":"– (informe perímetro e pé-direito)"}`;

/* ---------- formulário de medição ---------- */
function campoNum(k,l,v,ph=""){return `<label>${l}<input type="text" inputmode="decimal" data-mk="${k}" value="${esc(v??"")}" placeholder="${esc(ph)}"></label>`}
function camposMed(s,e){const sub=e.sub||opcoesModo(s)[0][0];let h="";
  if(sub==="dir")return campoNum("v","Quantidade ("+s.u+")",e.v);
  if(sub==="cnt")return campoNum("n","Quantidade (un)",e.n);
  switch(s.m){
    case "area":if(sub==="pct")return `<label>Base<select data-mk="base">${Object.entries(BASES).map(([k,v])=>`<option value="${k}" ${e.base===k?"selected":""}>${v[0].toUpperCase()+v.slice(1)}</option>`).join("")}</select></label>`+campoNum("pct","% afetado",e.pct,"ex.: 30");
      return campoNum("c","Comprimento (m)",e.c)+campoNum("l","Largura/altura (m)",e.l)+campoNum("n","Nº de vezes",e.n,"1")+campoNum("desc","Descontar (m²)",e.desc,"0");
    case "projecao":return campoNum("c","Comprimento em planta (m)",e.c)+campoNum("l","Largura em planta (m)",e.l)+campoNum("n","Nº de vezes",e.n,"1");
    case "comprimento":return campoNum("c","Comprimento (m)",e.c)+campoNum("n","Nº de trechos iguais",e.n,"1");
    case "volume":return campoNum("c","Comprimento (m)",e.c)+campoNum("l","Largura (m)",e.l)+campoNum("h","Altura/profundidade (m)",e.h)+campoNum("n","Nº de vezes",e.n,"1");
    case "vao_luz":case "vao_luz_2x":h=campoNum("l","Largura do vão (m)",e.l)+campoNum("a","Altura do vão (m)",e.a)+campoNum("n","Nº de vãos iguais",e.n,"1");
      if(s.c==="12.2.1")h+=`<label>Tipo de esquadria<select data-mk="fat"><option value="1" ${pnum(e.fat)!==2?"selected":""}>Com vidro (1× vão luz)</option><option value="2" ${pnum(e.fat)===2?"selected":""}>Veneziana (2× área)</option></select></label>`;return h;
    case "pintura_metal":if(sub==="tubo")return campoNum("d","Diâmetro Ø (m)",e.d,"ex.: 0,05")+campoNum("c","Comprimento (m)",e.c)+campoNum("n","Nº de peças",e.n,"1");
      if(sub==="cubo")return campoNum("c","Comprimento (m)",e.c)+campoNum("l","Largura (m)",e.l)+campoNum("h","Altura (m)",e.h)+campoNum("n","Nº de peças",e.n,"1");
      return campoNum("l","Largura do vão (m)",e.l)+campoNum("a","Altura do vão (m)",e.a)+campoNum("n","Nº de peças",e.n,"1")}
  return h}
function campos2(s,e){if(!s.u2)return"";let h="";
  if(s.u==="m²"&&s.u2==="m³")h=campoNum("esp","Espessura média (m) → volume",e.esp,"ex.: 0,10");
  else if(s.u2==="m")h=campoNum("c2","Comprimento (m)",e.c2)+campoNum("n2","Nº de trechos",e.n2,"1");
  else if(s.u2==="m²")h=campoNum("c2","Comprimento (m)",e.c2)+campoNum("l2","Largura (m)",e.l2)+campoNum("n2","Nº de vezes",e.n2,"1");
  else if(s.u2==="m³")h=campoNum("c2","Comprimento (m)",e.c2)+campoNum("l2","Largura (m)",e.l2)+campoNum("h2","Altura (m)",e.h2);
  return `<div class="card" style="background:#fafbf8;margin-top:10px"><b>2ª unidade (${esc(s.u2)})</b><div class="g2">${h}${campoNum("v2","ou valor direto ("+s.u2+")",e.v2)}</div></div>`}
