  m.addEventListener("change",ev=>{const k=ev.target.dataset.mk;if(k){e[k]=ev.target.value;atualiza()}if(ev.target.id==="mSub"){e.sub=ev.target.value;desenha()}});
  const salvar=async()=>{const r=calcMed({cod,e,sv:svSnap(s)},amb);
    if(r.erro&&!confirm(r.erro+".\n\nSalvar mesmo assim? A medição fica marcada como incompleta e não soma até ser corrigida."))return null;
    const at=camposAtivos(s,e);const ee={};for(const k of MED_CAMPOS)if(at.includes(k)&&e[k]!==undefined&&e[k]!=="")ee[k]=String(e[k]).slice(0,40);
    const local=limitar(m.querySelector("#mLocal").value,UI_MAX.curto),obs=limitar(m.querySelector("#mObs").value,UI_MAX.txt);
    let id=medId;
    await enqueue(()=>txRun(["servicos","medicoes"],t=>{const ss=t.objectStore("servicos"),ms=t.objectStore("medicoes");
      const rq=ss.index("ambienteId").getAll(ambId);rq.onsuccess=()=>{let sv=rq.result.find(x=>x.cod===cod);
        if(!sv){sv={id:uid(),estacaoId:amb.estacaoId,ambienteId:ambId,cod,estado:"exec",extra:!(s.t||[]).includes(amb.tipo),ordem:ordNow()};ss.put(sv)}
        else if(sv.estado!=="exec"){sv.estado="exec";ss.put(sv)}
        if(id){const g=ms.get(id);g.onsuccess=()=>{const o=g.result;if(!o)return;o.e=ee;o.local=local;o.obs=obs;if(!svOk(o.sv))o.sv=svSnap(s);o.modo=o.sv.m;ms.put(o)}}
        else{id=uid();ms.put({id,estacaoId:amb.estacaoId,ambienteId:ambId,servicoId:sv.id,cod,modo:s.m,sv:svOk(svSnap(s))?svSnap(s):null,e:ee,local,obs,ordem:ordNow(),criadoEm:Date.now()})}}}));
    alterou(amb.estacaoId);await marcarLevantado();return id};
  m.querySelector("#mOk").onclick=async()=>{const id=await salvar();if(!id)return;m.remove();ctx.scrollSvc=cod;await rerenderKeepScroll()};
  m.querySelector("#mFoto").onclick=async()=>{const id=await salvar();if(!id)return;m.remove();ctx.scrollSvc=cod;await rerenderKeepScroll();abrirCamera({estacaoId:amb.estacaoId,ambienteId:ambId,itemId:null,medicaoId:id})};
  if(m0)m.querySelector("#mDel").onclick=async()=>{const nf=ctx.D.fotos.filter(f=>f.medicaoId===medId).length;
    if(!confirm(`Excluir esta medição?${nf?`\nAs ${nf} foto(s) dela passam para as fotos gerais do ambiente.`:""}`))return;
    await enqueue(()=>txRun(["medicoes","fotos"],t=>{const fo=t.objectStore("fotos"),r=fo.index("ambienteId").getAll(ambId);r.onsuccess=()=>r.result.filter(f=>f.medicaoId===medId).forEach(f=>{f.medicaoId=null;fo.put(f)});t.objectStore("medicoes").delete(medId)}));
    alterou(amb.estacaoId);m.remove();await rerenderKeepScroll()};
