function quantEstHtml(D,N){
  const T=totaisEst(D),P=pendencias(D);const cods=Object.keys(T).sort(cmpChave);
  let h=`<div class="card"><div class="row"><b class="grow">${new Set(cods.map(chaveCod)).size} serviços com quantidade</b><span class="mu">${D.medicoes.length} medições</span></div>
    ${P.semVerif?`<div class="mu" style="margin-top:6px">⚠ ${P.semVerif} serviço(s) ainda não verificados nos ambientes.</div>`:`<div class="mu" style="margin-top:6px">✓ Todos os serviços verificados.</div>`}
    ${P.execSemMed.length?`<div class="mu" style="color:var(--red)">⚠ ${P.execSemMed.length} marcado(s) “Executar” sem medição: ${esc(P.execSemMed.slice(0,6).join("; "))}${P.execSemMed.length>6?"…":""}</div>`:""}
    ${P.medForaExec.length?`<div class="mu" style="color:var(--red)">⚠ Medições fora da conta (serviço não está em “Executar”): ${esc(P.medForaExec.slice(0,6).join("; "))}${P.medForaExec.length>6?"…":""}</div>`:""}
    ${P.unidMistas.length?`<div class="mu" style="color:var(--red)">⚠ Item(ns) com medições em unidades diferentes (catálogo trocado), totalizados em linhas separadas: ${esc(P.unidMistas.join(", "))}</div>`:""}
    ${P.medSemFoto?`<div class="mu">📷 ${P.medSemFoto} medição(ões) sem foto.</div>`:""}
    <button class="btn p w" style="margin-top:10px" data-a="expXlsx">📊 Gerar planilha de quantitativos (.xlsx)</button></div>`;
  let cap=null;
  for(const k of cods){const t=T[k],c=t.cod,s={...svcInfo(c),u:t.u,u2:t.u2,d:t.d,g:t.g||svcInfo(c).g};
    if(capitulo(c)!==cap){if(cap!==null)h+="</div>";cap=capitulo(c);h+=`<h2>${esc(cap)}. ${esc(s.g)}</h2><div class="card">`}
    h+=`<div class="amb" style="cursor:default"><span class="num">${esc(c)}</span><div class="grow"><div>${esc(s.d)}</div><div class="mu">${t.ambs.size} ambiente(s) · ${t.n} medição(ões)${t.erros?` · <span style="color:var(--red)">${t.erros} incompleta(s)</span>`:""}</div></div><b style="white-space:nowrap">${fq(t.q1,s.u)} ${esc(s.u)}${s.u2?`<br>${fq(t.q2,s.u2)} ${esc(s.u2)}`:""}</b></div>`}
  if(cap!==null)h+="</div>";
  if(!cods.length)h+=`<div class="empty">Nenhum quantitativo ainda.<br>Abra um ambiente na aba Campo, marque <b>Executar</b> nos serviços e lance as medições.</div>`;
  return h}

