  const dn=sheets.map((s,i)=>(s.printTitles?`<definedName name="_xlnm.Print_Titles" localSheetId="${i}">'${nomes[i].replace(/'/g,"''")}'!$${s.printTitles.replace(":",":$")}</definedName>`:"")+(s.autofilter?`<definedName name="_xlnm._FilterDatabase" localSheetId="${i}" hidden="1">'${nomes[i].replace(/'/g,"''")}'!${s.autofilter.replace(/([A-Z]+)(\d+)/g,"$$$1$$$2")}</definedName>`:"")).join("");
  z.file("xl/workbook.xml",`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><bookViews><workbookView activeTab="0"/></bookViews><sheets>${nomes.map((n,i)=>`<sheet name="${XLX(n)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join("")}</sheets>${dn?`<definedNames>${dn}</definedNames>`:""}<calcPr calcId="191029" fullCalcOnLoad="1"/></workbook>`);
  z.file("xl/_rels/workbook.xml.rels",`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((s,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join("")}<Relationship Id="rId${sheets.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`);
