  const figsMed=m=>D.fotos.filter(f=>f.medicaoId===m.id).map(f=>N.foto[f.id]).filter(Boolean);
  const execSet=new Set(D.servicos.filter(s=>s.estado==="exec").map(s=>s.ambienteId+"|"+s.cod));
  // 1. Resumo
  const R=[[{v:"QUANTITATIVOS DE CAMPO – ESTAÇÃO "+e.nome.toUpperCase(),s:4}],[],
    [{v:"Estação",s:8},e.nome],[{v:"Linha",s:8},e.linha||""],[{v:"Data(s)",s:8},e.datas||""],[{v:"Equipe",s:8},{v:String(e.equipe||"").split("\n").filter(Boolean).join("; "),s:9}],
    [{v:"Gerado em",s:8},xlData(new Date(),11)],[{v:"Referência",s:8},{v:"Caderno de Especificações Técnicas e Metodologia Executiva – Lote 1 (Anexo I do TR). Critérios de medição conforme o caderno.",s:9}],[],
    [{v:"Ambientes",s:8},INT(D.ambientes.length)],[{v:"Serviços com quantidade",s:8},INT(nCods)],[{v:"Medições",s:8},INT(D.medicoes.length)],[{v:"Fotos",s:8},INT(D.fotos.length)],[],
    [{v:"PENDÊNCIAS",s:8}],[{v:"Serviços não verificados",s:8},INT(P.semVerif)],[{v:"“Executar” sem medição",s:8},INT(P.execSemMed.length)],[{v:"Medições fora da conta (serviço sem “Executar”)",s:8},INT(P.medForaExec.length)],[{v:"Itens com unidades diferentes",s:8},INT(P.unidMistas.length)],[{v:"Medições sem foto",s:8},INT(P.medSemFoto)],[],
    [H("Capítulo do caderno"),H("Serviços com quantidade"),H("Medições")]];
  const caps={};const vistoCap=new Set();for(const key of cods){const c=T[key].cod,k=capitulo(c);caps[k]=caps[k]||{g:T[key].g||svcInfo(c).g,n:0,m:0};if(!vistoCap.has(c)){caps[k].n++;vistoCap.add(c)}caps[k].m+=T[key].n}
  for(const k of Object.keys(caps).sort((a,b)=>a-b))R.push([T3(k+". "+caps[k].g),INT(caps[k].n),INT(caps[k].m)]);
  if(P.execSemMed.length){R.push([]);R.push([{v:"Itens marcados “Executar” sem medição",s:8}]);P.execSemMed.forEach(x=>R.push([{v:x,s:9}]))}
  if(P.medForaExec.length){R.push([]);R.push([{v:"Medições fora da conta (marque “Executar” para incluir)",s:8}]);P.medForaExec.forEach(x=>R.push([{v:x,s:9}]))}
  if(P.unidMistas.length){R.push([]);R.push([{v:"Itens com medições em unidades diferentes (catálogo trocado) – uma linha por unidade em Quantitativos",s:8}]);R.push([{v:P.unidMistas.join(", "),s:9}])}
  // 2. Quantitativos
  const Q=[[H("Item"),H("Serviço"),H("Un"),H("Quantidade"),H("Un 2"),H("Quantidade 2"),H("Ambientes"),H("Nº med.")]];const mQ=[];let cap=null;
  for(const key of cods){const t=T[key],c=t.cod,mist=P.unidMistas.includes(c),s={u:t.u,u2:t.u2,d:t.d+(mist?" ⚠ medições em "+t.u+" (há outra linha deste item em outra unidade)":""),g:t.g||svcInfo(c).g};
    if(capitulo(c)!==cap){cap=capitulo(c);Q.push([{v:cap+". "+s.g.toUpperCase(),s:5},{v:"",s:5},{v:"",s:5},{v:"",s:5},{v:"",s:5},{v:"",s:5},{v:"",s:5},{v:"",s:5}]);mQ.push(`A${Q.length}:H${Q.length}`)}
    Q.push([T3(c),T3(s.d),T3(s.u),NUM(t.q1),T3(s.u2||""),s.u2?NUM(t.q2):T3(""),T3(ambOrd.filter(a=>t.ambs.has(a.id)).map(nomeAmb).join("; ")),INT(t.n)])}
